NAME = 'PohnOld: Old Public Domain Pohnpeian Bible'
BOOK = 'Acts'

CHAPTERS = {
    1: {
        1: 'MAING Teopilus, i wiadar tapin kasoi duen meakan, me Iesus kotin tapiadar, duen a wiawia o kaukawewe karos.',
        2: 'Lao lel ran en a peukedala mon a kotin kakalik ong wanporon akan, me a kotin piladar ren Ngen saraui,',
        3: 'Me a pil kotin kasansale ong pein i ieias ki kilel melel toto murin a kalokolok o a pwara dong irail ran paeisok o kapakaparokeki duen tiak en wein Kot.',
        4: 'A ni a kotikot re’rail, a kotin kakaliki ong irail, ren der kowei sang Ierusalem, a ren auiaui, inau en Sam lao pwaidar, me komail ronga sang ia er.',
        5: 'Pwe Ioanes wia paptais ki pil, a komail pan paptais kila Ngen saraui ni eu ran me koren.',
        6: 'Irail lao pokon penaer, rap kalelapok re a potoan ong: Maing, ansau wet re pan kotin kapure dong Israel wei o?',
        7: 'A kotin masani ong irail: Menda re omail, en asa ansau de auer, me Sam okila nan pein a manaman?',
        8: 'A komail pan ale manaman en Ngen saraui, me pan di po omail; komail ap pan ai saunkadede kan nan Ierusalem, o Iudäa pon o Samaria, o lel wong irepan sappa.',
        9: 'A lao masanier mepukat, ap peukedalar ni ar kangkakil, pali en dapok pali idandalar i sang mon mas arail.',
        10: 'Ni ar kilekilang nanlang, ni ansaun a kotidala, kilang, ol riamen mi nan likau pwetepwet, kotikot re’rail.',
        11: 'Me pil masani: Ol en Kaliläa komail, da me komail sarakidang nanlang? Iei Iesus, me peukedala nanlang sang komail, a pan kotin puredo, duen komail udialer a kotidalar.',
        12: 'Irail ap purelang Ierusalem sang dol o, me ad a Oliwe, me koren iong Ierusalem; a doo sang al en sapat pot.',
        13: 'Irail lao kotilong ong, ap kotidang nan pera poa, wasa re kin kotikoteta, irail karos: Petrus, o Ioanes, o Iakopus, o Andreas, o Pilipus, o Tomas, o Partolomäus, o Matäus, o Iakopus nain Alpäus, o Simon Selotes, o Iudas ri en Iakopus.',
        14: 'Mepukat karos wiaki eu podidi ong kapakap, li akai pil iang irail, o pil Maria in en Iesus o ri a ol akan.',
        15: 'Ni ran oko Petrus ap uda nan pung en saulang kan masani (irail me impan epukiriek):',
        16: 'Ri ai kan, kisin likau en pungala, me Ngen saraui kalokaia ki Dawid mas o iran Iudas, me karedo, me saikidi Iesus oko.',
        17: 'Pwe a pil wadawad ong kitail, er o aleer pwais a dodok wet.',
        18: 'Nan ol men et pwaine kidar pwain en a sapung sap eu, a ni a dikaudi, ap lop pasang o kanangan kaped a ap poie sang.',
        19: 'Toun Ierusalem karos asada met. Ari, sap o adanekila akeldama ni pein arail lokaia; iet wewe: Sap en nta.',
        20: 'Pwe a intingidier nan puk en psalm: Im a en liselipingala o solar, me pan kauson lole, a amen me pan ale a koa.',
        21: 'Ari, amen sang ren ol akan, me poden iang kitail er, ni ansau me Kaun Iesus kotikot re atail,',
        22: 'Sang ni muein paptais en Ioanes kokodo lel ni ran o, me a kotin peukada sang kitail er, pan iang kitail wiala saunkadede en a kotin iasada.',
        23: 'Irail ari kileledi riamen: Iosep iei Parsapas, me pil ad a Iostos o Matias.',
        24: 'Irail ap kapakap masani: Maing, ir me kotin mangi mongiong en amen amen, re kotin kasansaleda, is me re kotin pilada ren me riamen et,',
        25: 'Pwe i en ale pwais a dodok wet o koa en wanporon, me Iudas pupe sang, pwen kolang deu a.',
        26: 'Irail ap kadoropwada. A doropwa ko ong Matias; i ari iang wadawad ong wanporon ekamen oko.',
    },
    2: {
        1: 'RAN en pentikos lao leler, irail karos kot pena wasa ta kis.',
        2: 'A madang ngil laud eu likamata ngil en melimel peidido sang nanlang o kadirela im o wasa, re kot pena ia.',
        3: 'A lo sirangerang akai likamata kisiniai pwarado sokedi pon amen amen.',
        4: 'Irail karos ap dire kila Ngen saraui ap pikikidi padaki wei ni lokaia toror, duen Ngen kotin kamasan irail ada.',
        5: 'Men Sus, ol lelapok ko sang nan wei karos pan lang kaikairu Ierusalem.',
        6: 'Irail lao ronger duen mepukat karos, ap pokon penaer o puriamui kila, aki amen amen ronger udan a lokaia.',
        7: 'Irail karos poneponeki o puriamuiki indada: Kilang, kaidin mepukat karos men Kaliläa, me kin padapadak?',
        8: 'A daduen, kit kin rong irail amen amen ni udan ngil atail?',
        9: 'Men Partien, men Medien, men Elam, o toun Mesopotamien, o Iudäa, o Kapadosien, o Pontus, o Asien,',
        10: 'O Prikien, o Pampilien, o Äkipten, o liman Lipien; salong Kirene, o men Rom, me mi wasa et, karos Sus oko o Proselit oko,',
        11: 'Men Kreta o men Arapien, iaduen kitail kin rong kin irail udan ngil atail ar katitiki manaman en Kot akan?',
        12: 'Irail karos ari pingidar o ponepondar, indada nan pung arail: Dakot met?',
        13: 'Akai lalaue indada: Irail dire kila wain kap.',
        14: 'A Petrus iangaki ekamen oko ap kotida, kapitie laudeda masani ong irail: Ol en Iudäa kan o komail karos, me kauson Ierusalem, komail en asa duen met, o komail rong mas ai padak!',
        15: 'Pwe mepukat kaidin sakaular, duen omail kiki ong, pwe apton auer kasilu en ran wet;',
        16: 'Pwe iei mepukat, me lolok ren saukop Ioel:',
        17: 'Kot kotin masanier: Ieteten me pan wiaui ni imwilan ran akan: I pan kamoredi Ngen i pon uduk karos. Noumail ol o li akan ap pan deideikop, o noumail manakap akan pan kilekilang kaudial akan, o noumail di ma kan pan auramenda;',
        18: 'A ni ran oko I pil pan kamoredi Ngen i pon ai ladu o lidu kan, rap pan deideikop.',
        19: 'O I pan kapwareda manaman akai nanlang pali poa, o kilel akai nin sappa pali pa: Nta, o kisiniai, o adiniai;',
        20: 'A katipin pan wukila rotorotala, a saunipong pan wiala nta mon ran lapalap o lingan en Kaun o pan pwarado.',
        21: 'O a pan wiaui ma meamen likwir ong mar en Kaun o, a pan dorela.',
        22: 'Ari ol en Israel, komail rong kasoi pot et: Iesus men Nasaret Ol amen, me Kot kotin kilele kidar nan pung omail dodok kelail akan o manaman akan, o kilel akan, me Kot kotin wiaki i nan pung omail, duen me komail pein asa;',
        23: 'I lao pangalar duen kupur en Kot erpit, komail ap saikikidi pa en me sapung kan, ap pasuredi ong ni lopu o kamatalar.',
        24: 'I me Kot kotin kaiasadar, ni a kotin lapwada sal en a matala, pwe a sota kak ong, en kolekol i.',
        25: 'Pwe Dawid masanier duen i: I ngingar Kaun o potopot mo i; pwe a kotikot ni pali maun i, pwe i ender mokid.',
        26: 'I me mongiong i peren kida, o lo i popoleki; pil uduk ai pan kamoledi ni kaporopor.',
        27: 'Pwe re sota pan kotin likidmaliela ngen i nan wasan mela pil sota kotin mueid ong, me sapwilim ar Saraui o pan mor pasang.',
        28: 'Re kotin kasansale ong ia er al en maur akan; re pan kotin kadir kin ia la popol mon silang ar.',
        29: 'Ri ai kan mueid ong ia, en aima padaki ong komail duen sam atail Dawid, me pil matalar o saredier, o sapwilim a sousou mi re atail lao lel ran wet.',
        30: 'A saukop amen, ap mangi, me Kot kotin kaula inauki ong i, me kisan wa men pan kaipokedi pon mol a.',
        31: 'Ari, ni a mamangi duen en Iesus a iasada, ap kotin masani, me a sota likidmalielar nan wasan mela, o pil uduk a sota mor pasang.',
        32: 'I Iesus, me Kot kotin kaiasadar, kit karos saunkadede en mepukat.',
        33: 'A lao sapwilekidar pali maun en Kot, a kotin aleer sang ren Sam, en kapwaiada inau duen Ngen saraui, ap kotin kamoredi, me komail kin udial o rongerong.',
        34: 'Pwe kaidin Dawid, me kotidala nanlang kan, a pein i kotin masani: Kaun o kotin masani ong ai Kaun: Mondi ni pali maun i!',
        35: 'I lao wiaki om imwintiti utipan nä om akan.',
        36: 'Ari, men Israel karos en asa melel, me Kot kotin kasapwilada i, en Kaun o Kristus i Iesus me komail kalopuelar.',
        37: 'Irail lao rongadar met, ap lel ong nan mongiong arail, re ap indai ong Petrus o wanporon tei kan: Ri at oko, da me sen wiada?',
        38: 'Petrus ap masani ong irail: Komail kalula, o amen amen en paptais ong ni mar en Iesus Kristus, pwe dip omail akan en lapwada. A komail pan tungole Ngen saraui.',
        39: 'Pwe nan inau wet ong komail o noumail seri kan, o ong irail karos men ilawei, me Kaun, atail Kot, pan kotin molipe.',
        40: 'O pil song en masan toto, me a kadede ong irail, o panaui kin irail, masani: Komail en dorela pein komail sang nan di sued wet!',
        41: 'Irail me duki ong a masan ap paptaisela; ari, ni ran o aramas impan silekid me saulangalar.',
        42: 'Irail dadaurata padak en wanporon akan, o ar minimin pena, o kamadip saraui, o kapakap akan.',
        43: 'Lomwi ap kipadi aramas karos o manaman o kilel akan toto wiauier ren wanporon akan.',
        44: 'O karos me posonla, kin pokopokon o aneki pena kapwa takis.',
        45: 'O netikila ar kapwa kan o nene ong irail karos, duen ar samama amen amen.',
        46: 'Irail ari kaukaule wia minimin eu nan im en kaudok o, o pilitiki pena prot nan im ar akan, o re mangamanga ni popol, o lolepot pena,',
        47: 'Kapikapinga Kot o konekon ren aramas karos. A Kaun o kotiki ong momodisou, me dorela kan ni ran karos.',
    },
    3: {
        1: 'A PETRUS o Ioanes wiaki eu kotidalang nan im en kaudok ni auer en kapakap, auer kaduau.',
        2: 'A ol amen me tikida nä a dangidang, me kin wisikedo pwiledi liman wanim en im en kaudok, me ad a lingan, ni ran karos, pwen wia poekipoeki ren me kin kolong ong nan im en kaudok.',
        3: 'A lao kilanger Petrus i Ioanes, ni ara pan kotilong ong nan im en kaudok, ap poeki, pwen ale meakot.',
        4: 'A Petrus i Ioanes masani i, ap masani ong: Saradang kit!',
        5: 'I ari saradang ira, kasikasiki, me a pan tungole meakot re’ra.',
        6: 'Petrus ap kotin masani: Sota ai silper de kold, a meakot mi re i, me i pan ki ong uk: Ukida mar en Iesus Kristus en Nasaret o alu!',
        7: 'I ari koledi pa a maun o kauada i, a nä a o tikil en nä ap madang kelailadar.',
        8: 'Ap lusada o alu iang ira lang nan im en kaudok, masimasiok sili, kapikapinga Kot.',
        9: 'O aramas karos kilang a alialu sili o kapikapinga Kot.',
        10: 'A irail asa, me i, me kin poekipoeki liman wanim lingan en im en kaudok, irail pingkidar o poneponeki duen me wiaui ong i er.',
        11: 'A ni a iang Petrus, o Ioanes, aramas karos puriamuiki, ap tang penang irail nan palank, me ad a palank en Salomo.',
        12: 'Petrus lao masani mepukat, ap kotin masani ong pokon o: Ol en Israel, da me komail puriamui kila met? De da me komail kilekilang kin kit, likamata kit me kakelada i ni pein at kel de lelapok?',
        13: 'Kot en Apraam, o Isaak, o Iakop, Kot en sam atail akan kalinganada sapwilim a ladu Iesus, me komail pangala o likidmaliela ren Pilatus ni a kileledier, me a pan lapwada i.',
        14: 'A komail likidmaliela me Saraui o, o me Pung, ap poeki lolap amen, en lapwa dong komail.',
        15: 'A komail kamatalar tapin maur, me Kot kotin kaiasadar sang ren me melar akan, kit kin saunkadede en mepukat.',
        16: 'Aki poson mar a, mar a ap kakelada men et, me komail kin kilang o asa, o a poson kare ong i kelail melel wet mo omail karos.',
        17: 'Ari ri ai kan, i asaer, me omail sasa, me komail wiaki met, pil dueta omail saumas akan.',
        18: 'A ni mepukat Kot kotin kapwaiadar, me a kotin masanier ren saukop akan karos, me Kristus pan kalokolok.',
        19: 'Komail ari kalula o wukila, pwe dip omail akan en soredi sang, pwe muein kamaur en pwaida sang wasailen Kaun o.',
        20: 'A lao kotin poronedo, me loki ong komail er: Iesus Kristus,',
        21: 'Me pan kotikot nanlang lao lel ansau, me meakaros pan pungala, duen me Kot kotin masanier ren sapwilim a saukop saraui kan sang mas kokodo.',
        22: 'Pwe pil Moses kotin masanier: Kaun omail Kot pan kaipwi ong komail Saukop amen, ipwin ri omail akan dueta ngai, i me komail en ronga sang meakaros, me a pan kotin masani ong komail.',
        23: 'A iet me pan wiaui: Aramas karos, me kang peiki ong saukop o, pan kasapokela sang ren aramas.',
        24: 'A saukop karos irerokedo sang Samuel, karos me padapadak pil kokoper duen ran pukat.',
        25: 'Komail sapwilim en saukop akan o en inau, me Kot kotin wiai ong sam atail akan ni a kotin masani ong Apraam: Kainok karos nan sappa pan paieki amen kadaudok om.',
        26: 'Kot kotin porone dong komail sapwilim a ladu mas ni a kotin molipe i; pwen kapaia kida komail, en kawuki sang komail kuros dip omail akan.',
    },
    4: {
        1: 'A NI ara padapadaki ong aramas akan, samero kan, o saumas en im en kaudok, o sadusär akai, ap pokon dong ira;',
        2: 'Pwe re makaraki ara kawewe ong aramas akan o ar padapadaki, me Iesus pan kotin kaiasada me melar akan.',
        3: 'Irail ap kol ira di o kila ira nan imateng lao manda, pwe a wasa pongier.',
        4: 'A me toto, me iang rongadar masan o, posonlar; ari, toto en ol akan impan limekid.',
        5: 'A mandan ran o saumas, o monsap, o saunkawewe kan pokon pene nan Ierusalem.',
        6: 'A samero lapalap Anas, o Kaipas, o Ioanes, o Aleksander, o karos, me kisan kainok en samero lapalap,',
        7: 'Irail pwiliki ira di nan pung arail, ap kainoma re’ra: Ni kel en is, de ni mar en is, me komail wiaki met?',
        8: 'Petrus me dir en Ngen saraui ap masani ong irail: Maing ko, saumas en wei o monsap en Israel komail,',
        9: 'Ma se pan pakadeikada, o komail kainoma re at ran wet, pweki dok mau ong aramas somau men, o da me a kelaile kida,',
        10: 'Komail o aramas en Israel karos en mangi, me mar en Iesus Kristus men Nasaret, me komail kalopuelar, me Kot kotin kaiasadar sang ren me melar akan, nan i eta, me men et uki o kelail kidar.',
        11: 'I takai o, me lokidokila ren komail sause kan, me id wiala takai en pukakaim.',
        12: 'O sota amen, me maur mi re a, pwe pil sota eu mar pan lang, me pakadara dong aramas, me kitail pan maur kida.',
        13: 'A ni ar kilekilanger en Petrus i Ioanes ara pereperen o so masak, rap puriamui kila, pwe re asaer, me ira aramas mal me sota iang skul, o sota non audaud, rap asaer, me ira ianger Iesus.',
        14: 'A ni ar kilanger aramas o, me kelailadar, uda imp ara, rap sasalar lokaia.',
        15: 'Irail lao kadar ira sang nan kapung, re ap kapukapung pena indada:',
        16: 'Da me kitail en wiai ong aramas pukat, pwe toun Ierusalem asaer, me ira wiadar kilel sansal eu, a kitail sota kak kalikama.',
        17: 'A pwe ede lolok sili nan pung en aramas akan, kitail en padik inapwi ira di, me ira de padaki ong aramas amen ni mar wet.',
        18: 'Irail lao eker ira do re ap inapwiedi me ira der pan padaki de kawewe ni mar en Iesus.',
        19: 'A Petrus o Ioanes sapeng masani ong irail: Iaduen, me pung pan kupur en Kot, sen pwili sang komail mon Kot? Pein komail kasaui!',
        20: 'Pwe se so kak so katitiki, me se kilanger o rongadar.',
        21: 'Irail ap kainapwi ira di kalaudela, re ap kadar ira la, pwe sota me re diaradar, me ira en kamekameki, pweki aramas akan, pwe karos, kapinga Kot, duen me wiauier.',
        22: 'Pwe aramas o, me manaman en kakelada wiaui ong, daulier saunpar paeisok.',
        23: 'Ira lao lapwadar, ap kola ren iang ara ko, kaireki meakan, me samero lapalap o saumas akan katiti ong ira.',
        24: 'A irail lao rongadar, rap wiaki eu potoan ong Kot: Maing ir me Kot, me kotin kapikadar lang o sappa, o madau o audepa’ra karos.',
        25: 'Ir me kotin masani ren Dawid, sapwilim ar ladu: Da me men liki kan lingarangaraki, o da me wei kan lamelameki me mal akan?',
        26: 'O nanmarki en sappa kan kangudier o saumas akan pokon pena, en palian Kaun o sapwilim a Kristus.',
        27: 'Pwe melel nan kanim wet irail karos pokon penaer, iet akan: Erodes, o Pontius Pilatus, iangaki men liki kan, o men Israel akan pwen palian sapwilim ar ladu saraui Iesus, me re kotin keiedier,',
        28: 'Pwen kapwaiada meakan, me lim ar o kupur ar kileledier, en wiaui.',
        29: 'Ari Maing, re kotin mangi arail lingarangar, kotiki ong sapwilim ar ladu kan, en kaloki ar masan ni peren.',
        30: 'O kotin kapa wei lim ar, pwen kakelada, o kilel, o manaman akan en wiauiki mar en sapwilim ar ladu saraui Iesus.',
        31: 'Ar kapakap apton nikier, wasa me re kot pena ia, ap mokimokid. Irail karos ap direkila Ngen saraui, ap padapadaki masan en Kot ni pereperen.',
        32: 'A mongiong o ngen en ir karos me posonlar, kin lamalam ta pot, o sota me indada duen ar kapwa: Ai met, pwe re aneki pena kapwa takis.',
        33: 'A wanporon akan me kelail ni arail kadede me Kaun Iesus kotin iasadar, a mak lapalap iang irail karos.',
        34: 'O solar amen irail, me so a tungol, pwe karos, me sap de im arail mia, ap netikilar o wado pwain en me netilar akan.',
        35: 'O pwilikidi ni aluwilu en wanporon akan, o nek ong amen amen duen ar samama.',
        36: 'A Ioses me wanporon akan ki ong mar a Parnapas, (iet wewe: Nain kapol), kadaudok en Lewi amen, men Sipern,',
        37: 'Me sap we mia, ap netikilar o wado pwain a, pwilikidi ni aluwilu en wanporon akan.',
    },
    5: {
        1: 'A OL amen ad a Ananias o a paud Sapira netikila sap eu,',
        2: 'Ap okisang kisan pwain a, me a paud iang asa, o wado lu en moni, pwilikidi ni aluwilu en wanporon akan.',
        3: 'A Petrus masani: Ananias menda Satan kadirela mongiong om, pwen likam ong Ngen saraui o okisang kisan pwain en sap o?',
        4: 'Kaidin udan om, ma a sota pan netila? O kaidin insen om ni a netilar? A menda koe inauki ong nan pein mongiong om mepukat? Kaidin aramas, me koe likam ong, pwe ong Kot.',
        5: 'Ananias lao rongadar masan pukat, ap pupedi mela. A karos, me rongerong mepukat, masakadar kaualap.',
        6: 'A manakap oko ap udar, kidim pena i, wala sang, sarepedier.',
        7: 'Kadekadeo murin auer silu a paud pwarado, a sota asa, me wiauier.',
        8: 'Petrus ap masani ong i: Katitiki ong ia, ma koma netikila sap o ni pwain wet? A sapeng: Ei i eta.',
        9: 'Petrus ap masani ong i: Menda koma inauki pena, en kasongesong Ngen en Kaun o? Kilang, nä en me sarepedier om paud mier mon wanim o, o re pan wa uk ala.',
        10: 'I ap madang pupedi ni aluwilu a mela. A manakap oko lao pedelong ong, rap kilangada, me a melar, re ap wala sang o sarepedi i impan a paud.',
        11: 'Lomui kaualap kipadi momodisou karos, o karos me rongerong mepukat.',
        12: 'A kilel o manaman akan toto wiauiki lim en wanporon akan nan pung en aramas akan. Irail karos kot pena nan palank en Salomo ni lamalam ta pot.',
        13: 'A sota amen sang ren men liki kan kak pat ong irail, pwe karos waune kin irail.',
        14: 'A me toto, me posonlar wuki ong Kaun o irail me totoia, ol o li akan.',
        15: 'Irail wala me somau kan pon al akan, pwiliki irail edi pon pet o ro akan, pwe mot en Petrus en lel ong amen irail, a lau kotido.',
        16: 'A toun kanim akan, me mi impa, pwara dong Ierusalem, wado me somau o me kalokolokki ngen saut akai, irail karos ap kelailadar.',
        17: 'A samero lapalap o karos me iang i, me pwin en sadusär, ap uda makar kida kaualap,',
        18: 'Koledi wanporon akan o ki irail la nan imateng.',
        19: 'A tounlang en Kaun o kotin ritingada wanim en imateng oko ni pong, o kotin kalua irail la liki masani:',
        20: 'Komail kola sansal mon aramas, padaki ong irail nan im en kaudok duen masan kan karos en maur wet.',
        21: 'Irail lao rongadar met, rap sangkonai ong nan im en kaudok o kaweweda. A samero lapalap o iang oko ap kodo, eker pena kapung, o saumas en men Israel akan karos, o ilakwei ong imateng o, pwe irail en wisikedo.',
        22: 'A ladu kan lao pwarado, rap diaradar, me re solar mi nan imateng o, re ap purodo katitiki,',
        23: 'Indada: Se diaradar imateng a ritidier mau, o pwin silepa ar uda mon wanim oko, a se lao ritingadar, sota amen me se diar lole.',
        24: 'A kapin en im en kaudok, o samero lapalap akan lao rongada duen lokaia pukat, re ap ponepon kidar o sota asa, da imwin mepukat.',
        25: 'Amen ap pwarado kaire kin irail: Kilang, ol oko, me komail kilang nan imateng, u nan im en kaudok, padapadaki ong aramas akan.',
        26: 'Kapin iangaki ladu kai ap koieila uk irail do, a re kadek ong irail, pwe re masak aramas akan, pwe re de kate irail.',
        27: 'Irail wa ir do, ap kidi ong mon kapung o, a samero lapalap idok re’rail.',
        28: 'Masani: Kit so inapwi komail edi kaualap, me komail ender kawewe ni mar wet? A kilang, komail kadire kila Ierusalem omail lamalam o, o komail kin men kapokon ong kit ntan aramas men et.',
        29: 'Petrus o wanporon akan ap sapeng masani: Kitail en oke Kot mon aramas!',
        30: 'Kot en sam atail akan kaiasadar Iesus, me komail kamatalar, pwe komail pasuredier i ong ni lopu eu.',
        31: 'Nan i me Kot kotin kasapwila kidar pali maun a, pwen Kaun o Saunkamaur, pwen kotiki ong men Israel, en kalula o lapwa pan dip akan.',
        32: 'A kit me sapwilim a saunkadede ni mepukat, pil Ngen saraui me Kot kotiki onger ren me peiki ong i.',
        33: 'Irail lao rongadar met, re ap lingarangar kaualap o kapikapiki pena, en kame ir ala.',
        34: 'Amen ap uda nan kapung o, Parisär amen ad a Kamaliel, saunkawewe amen, me masamas ren aramas karos, me masani, ren kila liki ol oko ansau kis.',
        35: 'A masani ong irail: Ol en Israel komail, kalaka aramas pukat, me komail pan wia!',
        36: 'Pwe ni ran tei ko Teudas udar ponmasoki, me a me lapalap, a ol impan papuki iangala i, I ari kamelar o karos, me peiki ong i, muei pasang o soredier.',
        37: 'A murin ol o Iudas en Kaliläa ap uda ni ansaun wadawad o kaweid sapung aramas toto, ren tuki ong i. Ari, a pil melar o karos, me iang i, muei pasanger.',
        38: 'I ap panaui komail, en sopwei sang aramas pukat, o der doke irail, pwe ma lamalam o wiawia en me ren aramas, a pan soredi,',
        39: 'A ma ren Kot, komail sota kak kawe ir ala, pwe komail de kadiarokada, me kin palian Kot.',
        40: 'Irail ari peiki ong i. Re lao ekeredo wanporon akan o woki irail, re ap inapwiedi, ren der padak ni mar en Iesus, o kadar ir ala.',
        41: 'Irail ari koiei sang ni momod en kadeik o, o peren kida, me re war ong kamekameki mar a.',
        42: 'A ran karos re sota dukedi sang arail kawewe nan im en kaudok o nan deu arail akan, o re padapadaki me Iesus me Kristus.',
    },
    6: {
        1: 'A TOUNPADAK kan lao totolar ni ran pukat men Krik kai ap lipaned ong men Ipru, aki sota me apwali ar li odi kan ni ar dodok en ran akan.',
        2: 'Ekriamen oko ap molipe pena tounpadak kan masani: A sota mau ong, sen muei sang masan en Kot, pwen papa ni tepel.',
        3: 'Ari ri (at) akan, rapaki sang nan pung omail ol isimen, me kalok mau, me dir en Ngen (saraui) o lolekong, me sen kasapwiladang dok wet!',
        4: 'A kit pan apapwalita kapakap o dodok pan masan o.',
        5: 'Pokon o ari peren kida kaparok pot et. Re ap piladar Stepanus, ol amen, me dir en poson o Ngen saraui, pil Pilipus, o Prokorus, o Nikanor, o Timon, o Parmenas, o Nikolaus, proselite sang Antiokien amen.',
        6: 'Re kidang irail mon wanporon akan. Re lao kapakaper ap kidang po’rail lim ar.',
        7: 'Masan en Kot ari pwaida kaualap, o tounpadak kan madang totolar nan Ierusalem, o samero toto pil iang lamalam o.',
        8: 'A Stepanus, me dir en poson o kelail, ap wiadar manaman o kilel laud kai nan pung en aramas akan.',
        9: 'A akai me udar, me kisan sinakoke en Liperti o men Kirene, o men Aleksandrien, o men Silisia, o Asien akamai ong Stepanus.',
        10: 'A re sota kak palian en Stepanus a kupurokong o Ngen o, me audeda i.',
        11: 'Irail ari pwain ong ol akai, pwen katiti: Se ronger, me a lalaue moses o Kot.',
        12: 'Irail pil kamakarada aramas, o saumas akai, o saunkawewe, re ap saikidi i o koledi, re ap wa dong i mod en kadeik o,',
        13: 'O kapwareda saunkadede likam akai, me katitiki: Aramas men et sota kin dukedi sang a lalaue wasa saraui et o kapung.',
        14: 'Pwe se ronger, me a katitiki, me Iesus en Nasaret pan kawela wasa et o kawilianla lamalam kan, me Moses kotiki ong kitail er.',
        15: 'A karos, me iang mod ong kapung o, kangkakil i, kasauiada, me silang a dueta silang en tounlang amen.',
    },
    7: {
        1: 'SAMERO lapalap ap masani: Melel mepukat?',
        2: 'A masani: Ri ai o sam ai kan, komail rong, Kot en lingan kotin pwara dong sam atail Apraam ni a kotikot Mesopotamien, ni a saikenta kotikot Aran,',
        3: 'O kotin masani ong i: Kowei sang nan sap om o sang ren sau om, ko wong eu sap, me I pan kasale ong uk!',
        4: 'I ap lipa sang nan sap en Kaltäa o kotikot Aran. Sam a lao matalar, a kotin kalua wong i sap wet, wasa komail kotikot ansau wet.',
        5: 'I ari sota kotin mueid ong i, en sapaneki sap o, sota wasa, me laude ong pat en nä eu, ap kotin inauki ong i, ni ansau saikenta sapwilim a seri, me a pan kotiki ong i o kadaudok a, en sapaneki.',
        6: 'A iet duen me Kot kotin masani: Kadaudok a pan kakairu nan sap en men wai, o re pan lidula, o kanaudokala saunpar papuki.',
        7: 'O Kot kotin masani: I pan kadeikada toun wei o, me re kin liduliduwi. A murin met re pan lipa sang sap o, ap kaudok ong ia sap wet.',
        8: 'I ari kotiki ong irail inau en sirkomsais. A ap wiadar Isaak o sirkomsais i ni ran kawalu, a Isaak wiadar Iakop, a Iakop sam atail ekriamen oko.',
        9: 'A sam atail oko peirinki Iosep ap netikilang i Äkipten. A Kot me kotin apwali i,',
        10: 'O kotin dorela i sang ni a apwal akan karos, o kotiki ong i konekon ong kupurokong mon Parao, nanmarki en Äkipten. I ap kasapwilada i, en kaun en Äkipten o a dipisou karos.',
        11: 'Muein lek ap kipadi sap en Äkipten karos o Kanaan; i ansau o me apwal melel, o sam atail akan sota diaradar sak ar kisin sak.',
        12: 'A Iakop lao mangi, me manga mi Äkipten, ap kotin poronelar mas sam atail akan.',
        13: 'A lao kariapak Iosep ap diarokadar ren ri a ol akan, o sau en Iosep sansaledo ren Parao.',
        14: 'Iosep ap ilake dong sam a Iakop, pwen kotilang re a o sau i kan karos, irail me isiakan limen.',
        15: 'Iakop ap kotidilang Äkipten o matalar, i o sam atail akan.',
        16: 'Irail ari wisikelang Sikem o saredier nan sousou o, me Apraam netiekida moni kai sang ren nain Emor oko, sam en Sikem.',
        17: 'A ansau, me inau en Kot ong Apraam pan pwaida, lao korendor, men Israel ap kaparapar o totolar nan Äkipten.',
        18: 'A lao lel amen nanmarki kaunda Äkipten, me sasa Iosep,',
        19: 'I me widiwidinga kainok atail oko, o wia sued ong sam (atail) akan, pwe ren kasela nairail kisin seri kan, pwe re de memaurata.',
        20: 'I ansau me Moses ipwidier, me seri kaselel amen, ap apapwalieta nan im en sam a saunipong silu.',
        21: 'A lao lokidokilar, sapwilim en Parao seripein ap dorela i o kakairada dueta udan na.',
        22: 'Moses ari padakeda ni song en lolekong en men Äkipten karos; a i me manaman ni a masan o wiawia kan.',
        23: 'A lao saunpar paeisok dauer poa, ap lamedar, en tu ong ri a ol akan men Israel.',
        24: 'A lao masani amen, me kalokolok mal, ap sauasa i o depuk ong, me kaloke mal, ap kotin kamelar ol en Äkipten.',
        25: 'Pwe a kupura, me ri a ol akan pan dedeki, me Kot pan kotin kapiti kin ir sang lim a; a re sota dedeki,',
        26: 'A mandan ran o a kotila re’rail ni ar akamai pena, ap men kotin kapol ira la, masani: Koma pirien eu, menda koma wia sapung nan pung oma?',
        27: 'A me wiada sapung ong men imp a o sikon wei i, inda: Is me kasapwil uk adar, pwen at saumas o saunkapung?',
        28: 'Koe pan kame ia la dueta koe kamela men Äkipten aio?',
        29: 'Moses ap tangki sang lokaia pot et o kakairu sili nan sap en Midian eu, wasa a kanaitikieda ol riamen.',
        30: 'Kadekadeo lao par paeisok dauer poa, tounlang amen ap pwara dong i ni nana Sinai nin tuka teketek umpumpul pot.',
        31: 'Moses lao masani, ap kotin puriamuiki kasansal o. A ni a koti ong, pwen masani, kapitie en Kaun o ap pei dong i:',
        32: 'Ngai Kot en sam om akan, Kot en Apraam, o Isaak, o Iakop. Moses ap kotin rerereda o masak udial i.',
        33: 'Kaun o ap kotin masani ong i: Ki sang sut ni nä om akan, pwe wasa koe u ia me saraui!',
        34: 'I kilanger kankangeranger en nai aramas akan, o I ronger ar sangesang, ap kodi dong kamaio wei ir ala. Ari kodo, I pan kadar uk alang Äkipten!',
        35: 'I Moses, me irail mamaleki ni ar indinda: Is me kasapwil uk ada, pwen at saumas o saunkapung? I me Kot kotin poronela, en saumas o saunkamaur ki lim en tounlang o, me kotin pwara dong i nan tuka teketek.',
        36: 'Iei i, me kalua ir sang o wiadar manaman o kilel akan nan sap Äkipten, o nan sed waitata, o nan sap tan saunpar paeisok.',
        37: 'I Moses, me masani ong men Israel: Kot pan kotiki ong komail saukop amen sang nan ipwin ri omail ol akan dueta ngai, i me komail en peiki ong!',
        38: 'Iei i, me mi nan momodisou nan sap tan ren tounlang o, me kotin mamasani ong i pon nana Sinai, o me kotin ieiang sam atail akan me kotin aleer masan en kamaur, pwen use dong kit.',
        39: 'Me sam atail akan kang peiki ong, ap siken wei sang irail i, o nan mongiong arail re men sapalang Äkipten,',
        40: 'Potoan ong Aron: Wiai ong kit at kot akan, me pan tiong mo at, pwe se sasa, da me wiaui ong Moses, me kalua kit sang nan Äkipten!',
        41: 'Irail ari wiadar dikedik en kaupul amen ni ran oko, o mairong ong kilel en ani mal o, o perenki, wiawia kan en pa arail.',
        42: 'Kot ap kotin saupei sang irail o kotin mueid ong irail ren kaudok ong usu pan lang akan duen a intingidier nan puk en saukop akan: Iaduen komail men Israel, komail mairongki ong ia man akan nan sap tan ni par paeisok?',
        43: 'Melel komail waroki ong mol ong en Molok, o usu en omail kot Rempan, dikedik kai, me komail wiadar, pwen pongi; a I pan kasapoke komail la palila sang Papilon.',
        44: 'Mol en kadede mi ren sam atail akan nan sap tan duen masan en i, me kotin mamasani ong Moses, me ren wiada duen kilel o, me a kotin udialer.',
        45: 'Me sam atail akan pil aleer, ap iang Iosua wala ni ar sapaneki sap en men liki kan me Kot kotin koko wei mon silang en sam atail akan lao lel muein Dawid.',
        46: 'Me konekon ren Kot o kotin anane kauadang Kot en Iakop mol eu.',
        47: 'A Salomo me kotin kauada tanpas eu.',
        48: 'A Wasa lapalap sota kin kotikot nan mol, me pa en aramas wiadar duen saukop o kin katitiki:',
        49: 'Nanlang deu i, o sappa utipa i, me Kaun o kotin masani. A im da, me komail men kauadang ia, de ia wasa, I en kamol ia?',
        50: 'Kaidin pa i, me wiadar mepukat karos?',
        51: 'Komail me katiwo o so sirkomsais nan mongiong o salong omail, komail kin kaokaoe Ngen saraui ansau karos, komail kin dueta sam omail akan.',
        52: 'Is ren saukop akan me sam omail akan sota kaloke? O re kamata ir ala, me kopador Pung men et, me komail pangalar o kamatalar.',
        53: 'Komail me aleer kapung ren tounlang kan, ap sota kapwaiada.',
        54: 'Irail rongadar mepukat, ap olar nan mongiong arail o re teterok ngi ong i.',
        55: 'A Stepanus dir en Ngen saraui kangkakil nanlang o udial en Kot a lingan o Iesus a kotikot ni pali maun en Kot,',
        56: 'Ap katitiki: Kilang, i ududial nanlang kan ar ritida, o Nain aramas a kotikot ni pali maun en Kot.',
        57: 'Irail ap weriwereda o pinale salong arail o wiaki eu tanga dong i.',
        58: 'Irail lao sikenewei sang nan kanim o, rap kate i. A saunkadede kan pwilikidier ar likau ni nä en manakap amen, me ad a Saulus.',
        59: 'Irail ari kate Stepanus ni a kapakap o inda: Maing Iesus, re kotin kasamo ngen i!',
        60: 'I ari kelepuki o ngil laudeda: Maing re der kapokon ong irail dip wet. A inda met, ap mairedi o ari.',
    },
    8: {
        1: 'A SAULUS pil peren kida a kamela. A ni ran ota ansaun kamekam en momodisou en Ierusalem tapida; karos ap muei pasang nan sap en Iudäa o Samaria, wanporon akan me so.',
        2: 'A ol lelapok kai sarepedi Stepanus o maieiki i kaualap.',
        3: 'A Saulus me kamueit pasang momodisou o kuli ong im karos, wala ol o li karos, kasedi ong irail nan imateng.',
        4: 'A irail me muei pasanger, kakan sili padapadak duen masan o.',
        5: 'Pilipus ap kotilang kanim en Samaria eu o padaki ong irail duen Kristus.',
        6: 'A aramas akan wiaki eu peiki ong meakan, me Pilipus padaki ong irail. Re rongerong i o kilang kilel akan me a wiadar.',
        7: 'Pwe ngen saut keredi sang ren me toto ni ar weriwer laud. O me kokon madak o nä dangidang toto me kelailadar.',
        8: 'O peren me lapalap nan kanim o.',
        9: 'A ol amen ad a Simon, me kin wun ani mas o, kotokotaue men Samaria, me inda duen pein i, me i me lapalap.',
        10: 'A irail karos peiki ong i, me tikitik o me lapalap akan katitiki: Men et iei manaman en Kot me lapalap.',
        11: 'A re kin peiki ong i, pweki a kin kotokotaue irail sang mas kokodo.',
        12: 'A re lao kamelele Pilipus, me padaki duen rongamau en wein Kot o duen mar en Iesus Kristus, rap paptaisela, ol o li akan.',
        13: 'Simon pil iang posonlar, I lao paptaiselar, ap waroki ong Pilipus. A lao udial kilel o manaman akan, me wiauier, ap puriamuiki.',
        14: 'Wanporon akan me kotikot Ierusalem lao mangi, me Samaria iang duki ong masan en Kot, rap poronelang irail Petrus o Ioanes.',
        15: 'Ira lao kotido, ap kapakapa kin irail, pwe re en tungole Ngen saraui.',
        16: 'Pwe a saikenta moredi ong amen irail. Re paptaiselar eta ni mar en Kaun Iesus.',
        17: 'Ira ari kotiki ong po’rail lim ar akan, irail ap aleer Ngen saraui.',
        18: 'Simon lao kilanger, me Ngen saraui kokido en wanporon oko ara pwil po’rail lim ar akan, ap men ki ong ira kisin moni.',
        19: 'Indada: Koma pil kotiki dong ia manaman wet, pwe ma i pan pwil pon amen pa i kat, i en ale Ngen saraui.',
        20: 'A Petrus masani ong i: Noum moni en iang uk lokidokila! Pweki om kiki ong, me mana en Kot kokido moni.',
        21: 'Nan sota pwais om de om tungol ni dodok wet, pwe mongiong om sota inen mon Kot.',
        22: 'Ari, kalukila om sued wet, o poeki ren Kaun o, ma a sota pan kotin makeki lamelam sued nan mongiong om.',
        23: 'Pwe i kilanger, me koe me dir en edi katik o tengiteng ni me sapung.',
        24: 'Simon ap sapeng indada: Koma kotin kapakapa kin ia ren Kaun o, pwe mepukat, me koma masani ong ia, ender pwai dong ia.',
        25: 'A ira lao katitiki o kotikida masan en Kaun o, ap purelang Ierusalem, o padak sili rongamau nan kisin kanim en Samaria toto.',
        26: 'A tounlang en Kaun o masani ong Pilipus: Uda kola pali air pon al o, me kodi sang Ierusalem, ko ong Kasa me tan!',
        27: 'I ari uda sapalewei. A kilang, ol en Etiopia, saumas manaman en Kandase, li nanmarki en Etiopia, me kokoaki a dipisou karos, me kotido, pwen kaudok nan Ierusalem.',
        28: 'A ni a purela sap we, a kotikot pon dakepa o dondoropwe saukop Iesaia.',
        29: 'Ngen o ap kotin masani ong Pilipus: Kai ong o iangala dakepa!',
        30: 'Pilipus ap tanga wong i, ap rongadar a dondoropwe saukop Iesaia masani: Komui weweki, me komui doropwe?',
        31: 'I ari masani: Pala i pan asa, ma sota, me pan kawewe ong ia? I ari poeki ren Pilipus en kereda mondi re a.',
        32: 'A iet wasa nan kisin likau o me a wadoker: Duen sip amen, me pakara wei, pwen kamela, o duen sippul, me kin nenenlata pan me kote sang wun a, iduen a sota kotin dauasa pasang silang i.',
        33: 'A ni a karakarak a solar pakadeikadar. A is me pan kak kaweweda duen sau i kan? Pwe a ieias wisike sanger sappa.',
        34: 'Saumas ap sapeng Pilipus masani: I men poeki re omui, is me saukop katitiki met? Duen pein i de duen amen?',
        35: 'Pilipus ap kotiki pasang au a, padaki ong i rongamau en Iesus, tapiada nan kisin likau wet.',
        36: 'A ni ara kokowei, ira lel ong pil apot, a saumas o masani: Kilang pil o, da me karompa, me i sota paptais ki?',
        38: 'I ap masani dakepa en udi. Ira karos ap kodi ong pil o, Pilipus o saumas o; i ari paptais i.',
        39: 'Ira lao kodado sang nan pil o, Ngen en Kaun o ap pokada sang Pilipus. Saumas o ap solar kilang i. I ari daulul kokowei popol.',
        40: 'Pilipus ap diarokadar Asdod; a dadaulular, padak sili rongamau nan kanim karos lao a lele dong Säsarea.',
    },
    9: {
        1: 'A SAULUS dadaurata a lingarangaraki tounpadak en Kaun akan, ap pan kame ir ala, o kola ren samero lapalap o,',
        2: 'Poeki re a kisin likau ong sinakoke en Damaskus akan, pwe ma a pan diar meamen, me iangala lamalam, ol de li i en sali irail edi o kalualang Ierusalem.',
        3: 'A ni a sapasapal kokola koren iong Damaskus, marain eu kodido sang nanlang, sereda i.',
        4: 'Ni a pupedi nani pwel, ap rongada ngil eu, me masani ong i: Saul, Saul, da me koe kame kin ia?',
        5: 'A ap inda: Is komui Maing? A kotin masani: Ngai Iesus, me koe kin kame.',
        6: 'Paurida, kolang nan kanim en, nan a pan loki ong uk, me koe en wiada.',
        7: 'A ol oko, me iang i kokola, sapaimokid, pwe re rongadar ngil o, ap sota amen me re kilangadar.',
        8: 'Saulus paurida sang nan pwel, mas a papad eta, ap sota kilang meamen. A re kolokol pa a, kalualang i Damaskus.',
        9: 'I ari sota kilang wasa pong sili pong. A so kang de nim meakot.',
        10: 'A tounpadak amen mi Damaskus, ad a Ananias me Kaun o kotin masani ong ni kasansal eu: Ananias! I ari potoan ong: Iet ngai Maing!',
        11: 'Kaun o ap kotin masani ong i: Paurida kowei ong nani al o, me ad a Inen, ap idok nan im en Iudas amen, me mar a Saulus en Tarsus. Pwe kilang, a kapakap',
        12: 'A kilanger ol amen ni kasansal eu, me ad a Ananias, me ko dong i o pwil poa pa a kan, pwe a en kilangki wasa.',
        13: 'A Ananias potoan ong: Maing, i rongadar ren aramas toto duen ol men et, duen a kin kaokaoe sapwilim ar saraui kan, me mi Ierusalem.',
        14: 'O a aleer sang ren samero lapalap akan manaman, en saliedi karos, me kin likwir ong mar omui.',
        15: 'A Kaun o kotin masani ong i: U kowei, pwe iei ol o, me I piladar, en wala mar ai ren men liki o nanmarki kan o men Israel.',
        16: 'Pwe I pan kasansale ong i duen won a pan kamekameki mar ai.',
        17: 'Ananias ari kola, pedelong ong nan im o, pwil poa pa a pokon, indada: Ri (ai) Saul, Kaun o me kotin porone ia do; iei Iesus, me kotin pwara dong komui nani al o ni omui kokodo, pwe komui en kilangada wasa o dire kila Ngen saraui.',
        18: 'A madang likamata un en mam akai, me pupedi sang ni mas a, i ari kilangadar wasa o udar paptaiselar.',
        19: 'I lao mangaer, ap kelailadar, ap mimieta ren tounpadak en Damaskus akan ran akai.',
        20: 'A madang padapadak nan sinakoke kan duen Iesus, me i sapwilim en Kot.',
        21: 'A karos, me rongerong i, puriamui kila indada: Kaidin i, me kin kaokaoe ir, me kin likwir ong mar wet nan Ierusalem o kodo wasa et, pwen sali ir edi, kalua ren samero lapalap akan?',
        22: 'A Saulus me manaman kokoda o kapingada Sus oko, me kauson Damaskus ni a kawewedar, me i me Kristus.',
        23: 'Kadekadeo murin ran toto Sus oko kapung pena en kamela i.',
        24: 'A Saulus ronger, me re masamasan i; irail pil masamasan wanim akan ni ran o ni pong, pwen kamela i.',
        25: 'A tounpadak kan ale i ni pong apiekidi kopou eu sang pon kel o.',
        26: 'A Saulus lao pwara dong Ierusalem a sosong waroki ong tounpadak kan, irail karos masak i, pwe irail sota kamelele, me i tounpadak amen.',
        27: 'A Parnapas ale i o kare dong i ren wanporon akan, o katiti ong irail, duen a kilangadar Kaun o nani al o, o me a kotin masani ong i, o duen a so masak padapadaki ni mar en Iesus nan Damaskus.',
        28: 'I ari iang irail er kotin pedepedoi sang o pedepedelong ong nan Ierusalem o padaki aima ni mar en Kaun o.',
        29: 'I o men Krik kai masan o akamai pena, a re song kamela i.',
        30: 'Saulang kan lao asaer, ap iang i kolang Säsarea, ap kadaralang i Taris.',
        31: 'A momodisou kan ap popol o pwaidar nan Iudäa, o Kaliläa, o Samaria, o re weweid ni masak en Kaun o, o toto kilar popol en Ngen saraui.',
        32: 'A Petrus lao kakan sili nan sap akan, a pil kotila ren me saraui kan, me kaukauson Lida.',
        33: 'A diaradar aramas amen wasa o, me ad a Äneas, me wonon par walu, pwe me kokon dangidang.',
        34: 'Petrus ari masani ong i: Äneas. Iesus Kristus kakel uk ada. Paurida, pein lim pena ki om! I ari paurida madang.',
        35: 'A karos me kaukauson Lida o Saron, kilangada i, re ap wuki ong Kaun o.',
        36: 'A tounpadak li amen mi Ioppe, me ad a Tapea (iet wewe: Torkas), i me dir en wiawia mau kan o kisakis wei.',
        37: 'A kadekadeo ni ran oko a somaudar o melar. Irail lao duper i, ap nekidala nan pera poa.',
        38: 'A Lida me koren iong Iope. Tounpadak kan lao ronger, me Petrus kotikot wasa o, rap kadarala ol riamen re a, poekipoeki: Kom der peikasal, koti dong kit!',
        39: 'Petrus ari kotida iang ir ala. I lao pwarado, re ap ukadala i pera poa, o li odi karos u impa, sangesang o kapwareda sakit o likau kan, me Torkas wiadar ni a mimi re’rail.',
        40: 'A Petrus kiiei sang ir karos, ap kelepuki kapakap, ap saupei ong kalep o masani: Tapea, paurida! I ari pad pasang, kilangada Petrus, ap modadar.',
        41: 'I ari koledi pa a, kauada i. A lao eker pena me saraui o li odi kan, ap kasale ong irail i a maureda.',
        42: 'Ari a loki sili nan Iope, o me toto posonla Kaun o.',
        43: 'I ari kotikoteta Iope ran toto ren saun me wiada kil en man amen, me ad a Simon.',
    },
    10: {
        1: 'OL amen mi Säsarea ad a Kornelius, me saumas en pwin en saunpei eu, me ad a men Italien,',
        2: 'Me lelapok o masak Kot iangaki toun im a karos, me poden kisakis ong aramas, o kapakap ong Kot ansau karos.',
        3: 'A masani ni kasansal eu tounlang en Kot amen, me pwara dong i ni klok silu, masani ong i: Kornelius!',
        4: 'A kangkakil i o masakadar, potoan ong: Maing, dakot? A kotin masani ong i: Om kapakap akan o koleir leler wasailen Kot.',
        5: 'Koe ari kadar wong Iope ol akai, ukedo Simon, me pil ad a Petrus,',
        6: 'Me kin kairu ren Simon saun wia kil en man, me im a sal ong sed;',
        7: 'A tounlang o, me kotin mamasani ong i, lao kotilar, ap ekeredo na ladu riamen o saunpei lelapok amen, me kin mi re a ansau karos.',
        8: 'A lao masani ong irail mepukat karos, ap kadar ir alang Iope.',
        9: 'A mandan ran o ni ar sapasapalwei o koren iong kanim o, Petrus ap kotila pon im o, pwen kapakap impan klok eisokriau.',
        10: 'Ap men sakadar o a pan sak. A ni ar kaonopadang i, ap masani kasansal eu:',
        11: 'A kilanger nanlang a ritidar o ed eu likamata tein pwainok kalaimun kokodi, me imwi kan pukopuk pena o pwilidi ong nani pwel.',
        12: 'Song en man en sappa karos mi lole, me kin aluki pa, o me laualo, o man korop kai, o manpir en pan lang.',
        13: 'O ngil eu peidi dong i masanier: Petrus, paurida, kamela o manga!',
        14: 'A Petrus potoan ong: Kaidin Maing, pwe i kaikenta manga me mal kot, de me samin.',
        15: 'A ngil o masani ong i kariapak: Meakot, me Kot kamakelekeladar koe der mamaleki!',
        16: 'Mepukat wiauier pan silepak! Ed o ap kapuredalang nanlang.',
        17: 'A Petrus ni a kotin ponepon kidar wewe en kasansal o, me a masanier, kilang, ol oko me pakadarado sang ren Kornelius, ap rapaki im en Simon o uda pan wanim o,',
        18: 'O likilikwir pepeidok, ma Simon, me pil mar a Petrus kotikot wasa o.',
        19: 'A Petrus ni a kotin madamadaua duen kasansal o, Ngen ap kotin masani ong i: Kilang ol silimen raparapa kin uk.',
        20: 'Uda o kodiwei iang irail o so peikasal, pwe Ngai me kadar irail do.',
        21: 'Petrus ap kodilang ren ol oko, masani: Kilang, iet ngai, me komail raparapaki. Da karepen omail kodo?',
        22: 'Irail inda: Kornelius saumas en saunpei amen, ol pung amen, me masak Kot, o kalok mau ren Sus akan karos, me mangier sang ren tounlang saraui en Kot amen, en poron dong komui, en kotido nan tanpas a, pwen mangi sang komui masan akan.',
        23: 'I ari kasamo ir long o kinte kin irail er. A mandan ran o a kotin iang ir wei; o saulang en Iope kai pil iang i.',
        24: 'A mandan ran o re leler Säsarea. A Kornelius kapokon pena sau i o kompokepa kan ap auiaui irail.',
        25: 'A Petrus lao pedelong ong, Kornelius ap tu ong i o pupedi ong ni aluwilu a o kaudok ong i.',
        26: 'A Petrus kauada i indada: Uda, pwe ngai pil aramas amen.',
        27: 'A ni ara masan pena, ap pedelong ong, diaradar me toto momod pena.',
        28: 'I ari masani ong irail: Komail asa, me a sota inen, ol en Sus amen en pat ong men liki amen de kola re a. A Kot kotin kasale ong ia, i ender mamaleki de sauteki amen aramas.',
        29: 'I me i koki do o so peikasal ni ar idok ia. Ari, i men kalelapok, da karep en omail eker ia do?',
        30: 'Kornelius ap masaniada: Mon pong pa pong ngai kaisesol lel auer wet. A ni klok duau i kapakap nan im ai. A kilang, ol amen me kot mo i, mi nan likau lingaling,',
        31: 'O masani: Kornelius, om kapakap me pwaida, o om koleir leler kupur en Kot.',
        32: 'Ari, ilakilang Iope, pwe Simon me pil ad a Petrus, en kodo. A kakairu nan im en Simon saun wia kil en man, me sal ong sed. A lao pwarado, a pan padapadaki uk.',
        33: 'Ngai ari pitipit ilakilang komui, a meid mau omui pwarador. Ari iet kit karos sansal mon Kot, pwe sen rong meakan, me Kot masani ong komui.',
        34: 'Petrus ap kotiki pasang silang i indada: Melel, i asaer, me Kot sota kin kotin lipilipiliki aramas,',
        35: 'A nan sap karos meamen masak i o wiawia me pung, nan i me konekon re a.',
        36: 'Masan o me a kotin kadara dong men Israel, en kaire kin irail popol ren Iesus Kristus. (Nan i me Kaun pan meakaros).',
        37: 'Komail asa masan me kalok sili me tapidar nan Kaliläa lel Iudäa pon murin paptais, me Ioanes wiada padak due.',
        38: 'Duen en Kot a kotin keiekier Iesus en Nasaret Ngen saraui o manaman, me kotin kakan sili wiawia mau o kakeladar me tanwar en tewil, pwe Kot kotin ieiang i.',
        39: 'A kit karos me saunkadede en meakaros, me a kotin wiadar nan sap en Sus akan o pil Ierusalem, me re pasuredi ong nin tuka o kamatalar.',
        40: 'Nan i me Kot kotin kaiasadar ni ran kasilu o kasaleda i.',
        41: 'Kaidin ong aramas karos, pwe ong saunkadede kai, me pilipildar ren Kot, kit me iang i sak o urak murin a iasadar sang ren me melar akan.',
        42: 'I ari masani ong kit, sen padapadak ong aramas o kadede melel, me i, me Kot kotin piladar, pwen Saunkapung pan me maur o me melar akan.',
        43: 'A saukop karos kin kadede duen i, me dip en ir karos, me poson i, pan lapwada pweki mar a.',
        44: 'A ni Petrus kotikida masan pukat Ngen saraui ap moredi pon karos, me rongerong padak o.',
        45: 'A me poson akan, kisan sirkomsais, karos me iang Petrus pwarador, puriamuiki, me Ngen saraui pil moredi pon men liki kan.',
        46: 'Pwe re rongadar ar lokaia kida ngil toror kapinga Kot. Petrus ap masanier:',
        47: 'Is me pan inapwiedi pil, me mepukat ender paptaisela, pwe re aleer Ngen saraui dueta kitail?',
        48: 'I ari masani, me ren paptaisela ni mar en Iesus Kristus. Irail ap poeki, a en mimieta re’rail ran akai.',
    },
    11: {
        1: 'WANPORON o saulang kan, me mi Iudäa, rongadar, me men liki kan pil aleer masan en Kot.',
        2: 'Petrus lao pwara dong Ierusalem, me kisan sirkomsais oko ap akamai ong i indada:',
        3: 'Kom pwarala ren ol akai me so sirkomsais oko o manga re’rail.',
        4: 'A Petrus pikikidi masani ong irail karos me wiauier irerokedo masani:',
        5: 'Ngai mi nan kanim Iope wia kapakap. O ni ai wukilar, i kilanger kasansal eu: Ed eu kodido sang nanlang likamata tein pwainok kalaimun eu, me imwi kan pukopuk pena o a kodido imp ai.',
        6: 'Ni ai kangkakil, i ap diar o kilanger man aluki pa en sappa kai, o man laoalo, o man korop, o manpir en pan lang.',
        7: 'Ngai ari rongadar ngil eu, me masani ong ia: Petrus, paurida, kamela o manga!',
        8: 'A ngai potoan ong: Kaidin Maing, pwe sota me mal kot, de me saut kin ko ong nan au ai.',
        9: 'A ngil kariapak sapeng sang nanlang: Meakot me Kot kamakelekeledar, koe der mamaleki!',
        10: 'Mepukat wiauier pan silepak, ap apdar nanlang.',
        11: 'A kilang, madang ol silimen kasinenda mon im, me i mi lole, me pakadara dong ia sang Säsarea.',
        12: 'A Ngen kotin masani ong ia, i en iang irail wei so peikasal; a saulang wonemen pukat pil iang ia. Kit ari pedelong ong nan im en ol o.',
        13: 'I ari kaire kin kit, duen a kilanger tounlang o kotikot nan im a, masani ong i: Kadara wong Iope ol akai, me pan ukedo Simon me pil ad a Petrus,',
        14: 'Me pan padaki ong uk, me koe o noumui kan karos pan maur kila.',
        15: 'Ni ai pikikidi padak, Ngen saraui ap moredi ong po’rail, dueta a kotin moredi ong po’tail ni tapi o.',
        16: 'Ngai ari tamanda masan en Kaun o, me a kotin masani: Melel, pil me Ioanes paptais kier, a komail pan paptais kila Ngen saraui.',
        17: 'Ari, ma Kot kotin kisakisa irail dueta a kotin kisakisa kitail er, kitail me posonlar Kaun Iesus Kristus, is ngai, pwe i en kak palian Kot?',
        18: 'Irail lao rongadar mepukat ap nenenla o kapinga Kot indada: Nan Kot pil kotiki ong men liki kan en kalula, pwen maurela.',
        19: 'A me muei pasang ni ansau en kamekam en Stepanus, kakan sili lel Pönisien, o Sipern, o Antiokien o sota padaki ong meamen pwe Sus akan eta.',
        20: 'A nan pung arail ol akai mia, men Sipern o Kirene, me pwara dong Antiokien, ap pil padaki ong men Krik rongamau en Kaun Iesus.',
        21: 'A lim en Kaun o ieiang irail o me toto posonlar wuki ong Kaun o.',
        22: 'Rong en mepukat ap peidong momodisou en Ierusalem. Ir ari poronelar Parnapas, pwen kokola lel Antiokien.',
        23: 'I lao pwarador o kilanger mak en Kot, ap peren kidar o panaui irail karos, ren kelail ni mongiong arail o podidi ong Kaun o.',
        24: 'Pwe i me ol kelail o mau amen, me dir en Ngen saraui o poson. A aramas toto me wuki ong Kaun o.',
        25: 'A ap kola Tarsus rapaki Paulus.',
        26: 'A lao diaradar i, ap ukedo i Antiokien. Ira ap mimi ren momodisou par eu o padapadaki ong me toto. A nan Antiokien tounpadak kan tapidar adaneki sapwilim en Kristus akan.',
        27: 'A ni ran pukat saukop akai ko dong Antiokien sang Ierusalem.',
        28: 'A amen irail, me ad a Akapus me u kokopki Ngen, me muei lek lapalap pan kipadi sappa; ari, a pwaidar ni muein Klaudius.',
        29: 'A irail inauki pena, me re pan kisakisa saulang kan, me mi Ierusalem duen ar kapwapwa amen amen.',
        30: 'Mepukat re wiadar; re kadar wong saunkoa kan Parnapas o Paulus me wala.',
    },
    12: {
        1: 'I ANSAU nanmarki Erodes pikikidi kame akai nan momodisou.',
        2: 'I ari kamata kila kodlas Iakopus ri en Ioanes.',
        3: 'A lao kilanger, me Sus oko peren kidar, ap pil saikidi Petrus. Nan i ansaun prot somut.',
        4: 'A saikidi i o kilang i nan imateng, o kasilaki i pwin en saunpei paieu. Pamen me wia eu pwin, pwe murin pasa a men kasale ong pokon i.',
        5: 'Petrus ari sensal nan imateng a momodisou poden kapakapki i ren Kot.',
        6: 'Pongpong mon Erodes pan kasansaleda i, a saimokela nan pung en saunpei riamen, salikidi sal mata riapot. A silepa ko masamasan imateng mon wanim ko.',
        7: 'A kilang, amen tounlang en Kaun o pwarado o marain eu sarada nan imateng o. I ari pikir Petrus ni pangepang o kapaurida i masani: Paurida pitipit! Sal mata ko ap pupedi sang ni lim a kan.',
        8: 'A tounlang masani ong i: Pirapirada o suteda! I ari wiadar met. A ap masani ong i: Upupedi o idauen ia do!',
        9: 'I ari pedoido sang o idauenla i, o a sota dedeki, me melel en tounlang a wiawia. Pwe a kiki ong, me a auramandar.',
        10: 'Ira lao kotin daulier pwin en silepa kaieu, o kariau, ira ap lel ong wanim mata, me salong kanim, i me pein ritida mo’ra. Ira ari kotila pon al apot. A tounlang ap madang kotin rir sang mo a.',
        11: 'A Petrus lao dedeki me wiauier, ap masaniada: I ap asa melel, me Kaun o kotin poronedo sapwilim a tounlang o kapit ia sang ni pa en Erodes o sang en Sus akan ar masamasan.',
        12: 'A ni a kotin madamadaua, ap lel ong im en Maria in en Ioanes, me pil ad a Markus, wasa me toto pokon ia wia kapakap.',
        13: 'A ni en Petrus a letelet ni wanim o, lidu men, ad a Rode, ap pwara dong rong.',
        14: 'A lao asa kapitie en Petrus, a sota ritingada wanim o pweki a peren. A a tanglong katitiki, me Petrus kot mon wanim o.',
        15: 'A irail indai ong i: Koe iakala. A i kelail indada, me melel. Re ap inda: Kaidin i, a sapwilim a tounlang o.',
        16: 'A Petrus wiawia leteleteta. Irail lao ritingada o kilanger i, re ap puriamui kilar.',
        17: 'A i olole irail, en nenenla. A ap masani ong irail duen Kaun o, me kotin kalua i sang nan imateng o, o pil masanier: Kaireki Iakopus o saulang kan mepukat! I ap kotiei sang kotilang ekis wasa.',
        18: 'A lao ran pasanger, saunpei kan ap puriamuiki kaualap en Petrus a pitilar.',
        19: 'A Erodes lao idok o so diaradar, ap itetokenkone silepa ko o masani, ren kamela. I ari kotilang Säsarea sang Ierusalem kaukauson ia.',
        20: 'A Erodes ongiongidar pan men Tirus o Sidon, re ap wiaki eu poto dong i kadekadeke Plastus saunkoa en nanmarki o poeki muei mau, pwe re kin memaureki sap en nanmarki.',
        21: 'A kadekadeo eu ran Erodes ap puriong likau en nanmarki, kaipokedi pon mol o kapakaparok ong irail.',
        22: 'A aramas akan ngisingis indada: Nan i kapitie en kot amen, a kaidin en aramas.',
        23: 'A madang amen tounlang en Kaun o poki i, pweki a so wauneki Kot. A maas akan me kangala i; i ari mela.',
        24: 'A masan en Kot pwaida o lok sili.',
        25: 'Parnapas i Paulus puredo sang Ierusalem, ira lao kanikielar ar dodok, o ira pil ukedo Ioanes, me ad a Markus.',
    },
    13: {
        1: 'NAN momodisou en Antiokien saukop o saunpadak kai mia. Iet akan: Parnapas, o Simeon me pil ad a Niker, o Lusius men Kirene, o Manaen, me iang monsap Erodes apwalidar, o Saulus.',
        2: 'A ni arail papa ong Kaun o, o kaisesol, Ngen saraui ap kotin masani: Katorore sang ong ia Parnapas o Saulus, pwen wia dok eu, me I ki ong ira er!',
        3: 'Irail ap kaisesol o kapakap o kidang po’ra pa ar, re ap kadar ira wei.',
        4: 'Ira ari me pakadara kila Ngen saraui ap kotila Seloisia, wasa ira kereda pon sop pot tangalang Sipern.',
        5: 'Ira lao mi Salamis, ap padaki duen masan en Kot nan sinakoke en Sus akan. A Ioanes papa men pil iang ira.',
        6: 'Irail lao kakan sili nan dake lel kanim Papos, rap diaradar ol amen, me kin kati ani, saukop likam amen, kisan men Sus, ad a Par Iesus,',
        7: 'Me kin mi ren Serkius Paulus ol lelapok amen. I me ekere dong i Parnapas o Saulus, pwe a men rongerong masan en Kot.',
        8: 'A Elimas widingak (pwe i wewe en ad a) palian ira, pwen kapure sang saumas ni poson o.',
        9: 'Saulus, me pil adaneki Paulus, dir en Ngen saraui, kangkakil i,',
        10: 'Indada: Koe meid dir en widing o mesued, o nain tewil o me kailongki me pung karos. Koe sota pan dukedi sang palian al inen en Kaun akan.',
        11: 'A kilang met, lim en Kaun o mi po om. A koe pan maskun, ap solar kilang katipin ansau kis. Ari, a madang ediedelar o rotalar; i ap raparapaki sili men ale pa a, en kaweid i.',
        12: 'Saumas lao masani me wiauier, ap posonlar, pwe a puriamuiki padak en Kaun o.',
        13: 'Paulus o a warok kai ap kotila sang Papos tangatang ko dong Perke nan wein Pampilia. A Ioanes muei sang ira, purelang Ierusalem.',
        14: 'A ira masalewei sang Perke o kotilang Antiokien en Pisidien o kotilong ong nan sinakoke ni ran en sapat kaipokedi.',
        15: 'A lao nikier ar dondoropwe kapung o saukop akan saumas en sinakoke kai ap ilakilang ira masani: Ri (at) oko ma masan en panau pot ong aramas pukat mi re oma, koma ari kida!',
        16: 'Paulus ap kotida ololeki lim a masani: Ol en Israel komail o me kin masak Kot, komail en rong!',
        17: 'Kot en men Israel pukat, me kotin piladar sam atail akan o kapakapaiada aramas oko ni ar kakairu sili Äkipten, o lim a manaman, me a kotin kalua kin irail sang wasa o.',
        18: 'A impan saunpar paeisok a kotin apapwali irail nan sap tan.',
        19: 'Kadekadeo a lao kotin koko sang wei isu nan Kanaan, ap kotin nek ong irail sap arail.',
        20: 'O murin met a kotiki ong irail saunkapung kan irerokedo par papuki limeisok lel ong saukop Samuel.',
        21: 'A sang ni ansau o re inong iong nanmarki amen. Kot ap kotiki ong ir Saul nain Kis, ol en kadaudok en Peniamin amen, saunpar paeisok.',
        22: 'A lao kasapokelar, ap kotiki ong irail Dawid, pwen nanmarki, me a pil kotin kileledier masani: I diaradar Dawid nain Iese, ol amen duen inong en mongiong i, me pan wiada insen ai karos.',
        23: 'Sang nan kadaudok a Kot kotikido Iesus, pwen Saunkamaur pan men Israel, duen sapwilim a inau.',
        24: 'Murin Ioanes a kotin padaki ong men Israel karos duen paptais en kalula mon a kotido.',
        25: 'A Ioanes lao kapwaiada sapwilim a dodok, ap kotin masani: Is me komail lamelame me ngai? Kaidin ngai i. A kilang amen kotido, kisin sal en sapwilim a sut i sowar en lapwada.',
        26: 'Komail ol o ri ai kan, komail kadaudok en Apraam, o meamen me masak Kot re omail, padak en kamaur pot et pakadara dong komail.',
        27: 'Pwe me kaukauson Ierusalem o ar saumas akan kapwaiada kokop en saukop akan, me kin wadawad ni sapat akan karos ni ar kadeikada i, pweki re sasa i.',
        28: 'A sota me re diaradar, me a kak kamata kila. Ari so, re poeki ren Pilatus, me a en kamatala i.',
        29: 'Irail lao kapwaiada karos, me intingkidi i, re ap kidi sang i nin tuka o kidi i nan sousou o.',
        30: 'A Kot me kotin kaiasada i sang ren me melar akan.',
        31: 'O ran toto me a kotin pwara dong me iang i kotilang Ierusalem sang Kaliläa, me sapwilim a saunkadede ong aramas akan.',
        32: 'A kit padaki ong komail rongamau duen inau ong sam atail akan,',
        33: 'Me Kot kotin kapwai ong kitail nairail seri kan, ni a kotin kaiasadar Iesus duen a intingidier nan psalm kariau: Koe nai Ol, I kanaitik uk adar ran wet.',
        34: 'A duen a kotin kaiasada i sang ren me melar akan, pwen der mor pasang, i me a kotin masanieki met: I pan ki ong komail pai melel en Dawid akan.',
        35: 'I me a pil masanieki ekis wasa: Re sota pan kotin mueid ong, sapwilim ar Saraui o pan mor pasang.',
        36: 'Pwe Dawid lao kapwaiada a papa ong kupur en Kot ni a ansau, ap saimokelar, a saredier impan sam a ko, ap mor pasang.',
        37: 'A i me Kot kotin kaiasadar, nan a sota kotin mor pasang.',
        38: 'Ari ri ai kan, komail asa, me lapwa pan dip akan ren men et kin kaloki ong komail.',
        39: 'A me pan poson i, nan i me pungalar sang meakaros, me komail sota kak pung kila kapung en Moses.',
        40: 'Ari, komail kalaka, pwe a depa pwai ong komail, me saukop akan masanier:',
        41: 'Kilang, komail me kin lalaue, puriamuiki o soredi, pwe I pan wia dodok eu ni omail ansau, me komail sota pan kamelele, ma amen pan kasokasoi ong komail due.',
        42: 'Irail lao pedoi sang ap poekipoeki, kasoi pukat en kalok ong irail ni ran en sapat kokodo.',
        43: 'A saraui lao nikier, men Sus o Proselit lelapok toto idauenla Paulus o Parnapas, me mamasani ong irail o panaui irail, ren podidi ong mak en Kot.',
        44: 'A ni sapat kokodo karos toun kanim o pokon pena, pwen rong masan en Kot.',
        45: 'A Sus akan lao kilanger pokon o, ap pepeirinki o lidere meakan, me Paulus kaweweda; re palian o lalaue.',
        46: 'A Paulus o Parnapas ap so masak katitiki: Masan en Kot en loki dong komail mas, a pweki omail kase sang, o wia kin komail sowar ong maur soutuk, kilang, se sope wei ong men liki kan.',
        47: 'Pwe iet duen me Kaun o kotin masani ong kit: Ngai me kasapwil uk adar, pwen marain pan men liki kan, pwe koe en kamaur sili lel sap karos.',
        48: 'Men liki kan lao rongadar met, ap peren kidar, o kapinga masan en Kot o karos, me kileledi ong maur soutuk, posonlar.',
        49: 'A masan en Kaun o lolok sili nan wei kan karos.',
        50: 'A Sus oko kamakarada li saupeidi lelapok o saumas en kanim kan, o kapei ong Paulus o Parnapas aramas o kasapoke ir sang nan sap arail,',
        51: 'A ira sipede sang ni aluwilu ar pwel, pwen kadede ong irail, ap kotilan Ikonien.',
        52: 'A tounpadak kan me dir kila peren o Ngen saraui.',
    },
    14: {
        1: 'A IET me wiauier nan Ikonien: Ira karos kotilong ong nan sinakoke en Sus oko, ap padapadak kelail, lao kisan men Sus o Krik toto posonla.',
        2: 'A Sus oko, me so poson, kamokimokid men liki kai o kalolap irail ong saulang kan.',
        3: 'A ira mimieta warai wasa o, o aima padapadak duen kupur en Kaun o, me kotin kapwaiada masan en kupur a, ni a kotin kasaleda kilel o manaman akan ki lim ara.',
        4: 'A toun kanim liak toror pasang. Akai me iang Sus oko, a akai iang wanporon akan.',
        5: 'A moromorong lao wiauier sang ren men liki kan o pil Sus oko iangaki ar saumas akan, pwen kame o kate ira,',
        6: 'Ira lao mangier, ap pitilang kanim Likaonien, o Listra, o Derpe, o sap me mi imp a,',
        7: 'Wasa o ira padapadak rongamau.',
        8: 'A ol amen momod Listra, me pat en nä luet o kokon dangidang sang ni a tikitik, me saikenta alu.',
        9: 'I me kin rongerong en Paulus a padak. A lao masani i, ap kotin kasauiada, me a poson itar ong en kakelailada,',
        10: 'Ap kotin kapitie laudeda masani: Ukida nä om! I ari masiokadar o aluwei.',
        11: 'Aramas lao kilanger, me Paulus kotin wiadar, rap ngilada kapitiki nin lokaia en Liakonien: Kot akan wia aramasala ap koti dong kitail.',
        12: 'Irail ari ki ong mar en Parnapas Iupiter, a Paulus Merkurius, pweki a kaunda kaparok.',
        13: 'A samero en Iupiter, me kin mi mon kanim o, ap wado kau ol o al en tuka kai mon kanim o, ap men iang pokon o wia mairong isis.',
        14: 'A wanporon oko Parnapas i Paulus lao mangi mepukat, ira ap ter pasang ara likau o tang wong nan pung en aramas akan likelikwir:',
        15: 'Maing ko, da me komail wiawiaki mepukat? Kit aramas dueta komail, ap padaki ong komail, pwe komail en wuki sang kot mal pukat, wuki ong Kot ieias, me kotin kapikadar lang, o sappa, o sed, o audepa’rail karos.',
        16: 'Me kotin mueid ong toun sap karos en wia pein insen ar mas o.',
        17: 'Ari so, a sota kotin okila pein i, pwe a kotin wiawia mau o kotiki ong komail katau sang nanlang o rak o, o kadireki nan mongiong omail manga o peren.',
        18: 'Ira kotin masani mepukat, a ekis ta, ira sota kak katukiedi en pokon o ar pan mairong ong ira.',
        19: 'A Sus oko ap kodo sang Antiokien o Ikonien, kamakarada aramas. Ir ari kate Paulus o uradokilang likin kanim o, re ap kiki ong, me a matalar.',
        20: 'A ni en tounpadak kan ar kapil pena i, a kotida ap kolong ong nan kanim o, a manda a iang Parnapas koieila Derpe.',
        21: 'Ira lao padapadak rongamau nan kanim o, o kasaulangalar me toto, ira ap purela Listra, o Ikonien, o Antiokien.',
        22: 'Ira kakelada ngen en tounpadak kan o panaui irail, me ren dadaurata poson, o me kitail en leleki wein Kot kamekam toto.',
        23: 'Ira lao kasapwilada saunkoa kai nan momodisou karos, ap kapakap o kaisesol, ap kapakapa ki irail ren Kaun o me re posonlar.',
        24: 'Ira kakan sili Pisidien ap lel ong Pampilien.',
        25: 'Ira lao padaki duen masan o nan Perke, ap kotilang Atalien.',
        26: 'A sang ni wasa o ira tangalang Antiokien, wasa ira sapwile kidar mak en Kot ong dodok o me ira kapwaiadar.',
        27: 'Ira lao pwarador, ap kapokon pena momodisou, rap kotin kasoia ong irail duen en Kot a kotin wiaki ira, o duen a kotin ritingada wanim en poson en men liki kan.',
        28: 'Ira ap kotikot warai ren tounpadak kan.',
    },
    15: {
        1: 'A AKAI me kodido sang Iudäa, ap padaki ong saulang kan: Ma komail sota sirkomsais duen tiak en Moses, komail sota pan kak maurela.',
        2: 'A irail lao liak toror pasang o akakamai ong Paulus o Parnapas, re ap inauki pena, me Paulus i Parnapas, o pil akai irail en kotidalang Ierusalem ren wanporon o saunkoa kan pweki mepukat.',
        3: 'Momodisou ap likid ir wei lao ekis wasa. Irail ap weweid nan Pönisien o Samaria o kasokasoiada duen en men liki ar wukila. Irail ari kaperenda melel saulang kan karos.',
        4: 'Irail lao lel Ierusalem, momodisou o wanporon, o saunkoa kan ap kasamo ir. Irail ap katitiki meakan, me Kot kotin wiaki irail er.',
        5: 'A akai kisan pwin en Parisär, me saulangalar, me uda indada: Me pung, en sirkomsais ir ala, o kapi ong irail, en wiawia kapung en Moses.',
        6: 'A wanporon o saunkoa kan pokon pena, pwen kaparok duen met.',
        7: 'Irail lao kapukapung pena warailar, Petrus ap kotida masani ong irail: Ri ai kan, komail asa, me mas o Kot kotin pil ia dar sang nan pung omail, pwe men liki kan en ronga sang nan au ai masan en rongamau o posonla.',
        8: 'A Kot me kotin ereki mongiong en aramas, kotin kadede irail o kotiki ong irail Ngen saraui dueta kitail,',
        9: 'O a sota kotin wiada irair eu nan pung en kitail o irail ni a kotin kamakel mongiong arail ki poson.',
        10: 'Ari, da me komail kasongesongki Kot, en kidang pon pop en tounpadak kan lopu eu, me sam atail akan o pil kitail sota kak wa.',
        11: 'A kitail kin kamekamelele, me kitail pan kamaureki mak en Kaun Iesus Kristus dueta irail.',
        12: 'A pokon o nenenlata o rongerong en Parnapas i Paulus ara katiti duen manaman oko o kilel kai, me Kot kotin wia kidar lim ara nan pung en men liki kan.',
        13: 'Irail lao nenenlar, Iakopus ap kaparok masanida: Ri ai kan komail rong ia!',
        14: 'Simon me kasoiada duen en Kot a kotin pwara dong men liki kan ni tapi o pwen pili sang irail kainok eu ong mar a.',
        15: 'Pwe iduen masan en saukop akan duen a intingidi:',
        16: 'Murin mepukat I pan puredo o kawiliakapada im en Dawid, me rongki pasanger, o pur ong kauada wasa me olar.',
        17: 'Pwe luan aramas akan en raparapaki Kaun o, pil men liki kan, me wan ad ai, iei me Kaun o masaniadar, me kin kotin wiawia.',
        18: 'Mepukat me lolok sang ni tapi o.',
        19: 'Ari iet me i kasauiada, kitail ender katoutoui irail me wuki ong Kot sang ren men liki kan.',
        20: 'A sen intinge wong irail, ren liki sang kasaut en kot mal akan, o nenek, o man mopelar akan, o nta.',
        21: 'Pwe sang mas kokodo saunkawewe en Moses kin mi nan kanim karos, pwe re kin padapadak duen i nan sinakoke kan ni ran en sapat akan karos.',
        22: 'Wanporon o saunkoa kan, o momodisou ap maukidar, en pilada ol akai sang ar pokon o porone ira wei iang Paulus i Parnapas, en kotila Antiokien: Iudas, me pil ad a Parnapas o Silas, ol pukat, me kaun pan saulang kan.',
        23: 'A iet eten, me re intingiedier ap kadar wong irail: Iet kit wanporon o saunkoa kan o saulang kan kadar wong komail, ri at akan, me ko sang ren men liki kan nan Antiokien, o Sirien, o Sisilia at ranamau.',
        24: 'Aki at ronger, me akai, me koiei sang re at, kin kaponepone kin ngen omail ar padak kan ni ar kasapunge komail lar indada: Komail en sirkomsais o kapwaiada kapung o; a se sota ki ong irail kusoned akan.',
        25: 'Kit ap wiaki eu ni at maukidar en piladar ol akai, ap kadar wong komail iangaki kompoke pat Parnapas o Paulus.',
        26: 'Ol oko me tonmeteki maur ara ong mar en Kaun Iesus Kristus.',
        27: 'Kit ari kadar wei Iudas o Silas, me pil pan kasoi ong komail mepukat.',
        28: 'Pwe Ngen saraui o kit kin kupukupura, me mau, se ender ki ong komail eu lopu; mepukat eta me kasampwal:',
        29: 'Komail liki sang uduk, me mairong ong kot likam, o nta, o man mopelar, o nenek. Ma komail liki sang mepukat, nan komail kin wiawia me mau. Ran kaselel!',
        30: 'Irail lao pakadarala, ap kotilang Antiokien, re ap kapokon ir pena, ki ong irail kisin likau o.',
        31: 'Irail lao wadoker, ap peren kidar kamait parail.',
        32: 'A Iudas i Silas, me pil saukop oko panaui kin saulang kan kasoi toto o pil katinai ir ada.',
        33: 'Irail mi wasa o lao ran akai, ap pakadarala popol sang ren saulang kan, pwe ren kola ren me kadar ira ala.',
        35: 'A Paulus i Parnapas kotikoteta Antiokien, kawewedar o padapadaki masan en Kaun o, o me toto pil iang.',
        36: 'Kadekadeo murin ran akai Paulus masani on Parnapas: Kita pan purela ren saulang kan, me mi kanim akan, wasa kita padakier duen masan en Kaun o, o kalekalelapok due’rail.',
        37: 'A Parnapas men ukada Ioanes, me pil ad a Markus.',
        38: 'A Paulus kupura, me a sota mau, ira en ukada i, me muei sang ira nan Pampilien o solar iang ira kolang dodok.',
        39: 'Ira ari akamai pena lao ira muei pasang. Parnapas ari ukada Markus tanga wong Sipern.',
        40: 'Paulus piladar Silas ap kotila. A saulang kan mueidela ira ni mak en Kot.',
        41: 'I ari kakan sili nan Sirien o Silisia katinada momodisou kan.',
    },
    16: {
        1: 'PAULUS ari kotilang Derpe o Listra. A kilang tounpadak amen mi wasa o, me ad a Timoteus, nain li en Sus me poson amen, a sam a men Krik.',
        2: 'Nan i kalok mau sili ren saulang en Listra o Ikonien akan.',
        3: 'Paulus kotin men, i en waroki ong i. I ari uk i o sirkomsais i, pweki Sus oko, me mi wasa o, pwe irail asaer, me sam a men Krik amen.',
        4: 'A ni arail kotikot sili nan kanim akan, re padaki ong irail me ren kapwaiada kusoned oko, me wiauier ren wanporon o saunkoa kan nan Ierusalem.',
        5: 'Momodisou kan ari kelailada ni poson o re totolar ni ran karos.',
        6: 'A Ngen saraui kotin inapwiedi, me ren der padak duen masan nan Asien, re ap kakan sili Prikien o Kalatien.',
        7: 'Irail lao pwara dong Misien, re song daulul wei ong Pitinien, a Ngen en Iesus sota kotin mueid ong.',
        8: 'Irail lao daulul lar Misien, ap kodilang Troas.',
        9: 'A kasansal eu pwara dong Paulus ni pong: Ol en Masetonien amen me uda, poekipoeki i indada: Kom koti dong Masetonien, sauasa kit!',
        10: 'A lao udialer kasansal o, kit madang kolang Masetonien, pwe se asaer, me Kaun o kotin molipe kit, en kolan padaki ong irail rongamau.',
        11: 'Kit ari masel wei sang Troas o inen wong Samotrasien, a manda lel ong Neapolis,',
        12: 'O sang wasa o lel Pilipi, kanim lapalap ni apali en Masetonien, me kisan sap en men Rom. Kit ari mimieta nan kanim o ran akai.',
        13: 'Ni ran en sapat se koiei sang kanim o, kolang pon pilap pot, wasa re kin kapakap ia. Kit ari mondi o kawewe ong li akai, me kin pokopokon wasa o.',
        14: 'A li amen ad a Lidia, men saunet en likau waitata, men Tiatira amen, me kin kaudok ong Kot. Nan i me rongerong kit. A Kaun o kotin ritingada mongiong i, pwen apapwali meakan, me Paulus masanier.',
        15: 'I o a penainai lao paptaiselar, ap poeki re at indada: Ma komail kasau ia da, me i posonlar Kaun o, komail pan pedelong ong nan im ai o kotikot ia; i ari ngidingide kin kit.',
        16: 'Kadekadeo ni at kolan kapakap lidu amen, me kin wun ani, ap tu ong kit, me kin kare ong moni toto ren a saumas kan ki a wun ani.',
        17: 'I me idauen Paulus o kit weriwer indada: Aramas pukat me sapwilim en Kot lapalap ladu ko, me kin padaki ong komail duen al en maur.',
        18: 'A mepukat a wiadar ran toto. A Paulus kupurola kaualap ap kotin saupeila masani ong ngen o: Ni mar en Iesus Kristus me i indai ong uk, keredi sang i! I ap keredi sang ni auer ota.',
        19: 'A saumas akan lao diarada, me solar kaporopor en ar men wiaki moni, ap saikidi Paulus o Silas, wai ira long dong wasan net ren saumas akan.',
        20: 'O kalua ira wei ren saunkapung kan katitiki: Aramas pukat kisan men Sus kin kaokaoe atail kanim,',
        21: 'O padapadaki tiak me sota pung se en ale de wiada, pwe kitail men Rom.',
        22: 'Aramas karos ap uda por ong ira, o saunkapung ko dere sang ara likau kan o kapi, ren woki ira.',
        23: 'Irail wokiwoki ira pan pak toto, rap kase ira di nan imateng o kapiedi silepa o, en katengeteng ira di.',
        24: 'A lao aleer kusoned wet ap kase ira di ong nan warong, en imateng o saliedi aluwilu’ra nin tuka kai.',
        25: 'A lao ni ailep en pong Paulus o Silas kapakap o melkaka ong Kot, o me salidi ko rongerong ira,',
        26: 'A sap o madang rerereda, kasukasuk en imateng mokidedar, wanim ko ap madang ritida o ar sal akan karos lapwadar.',
        27: 'A silepan imateng lao pirida sang a mair o kilang wanim ko ar ritidar, ap ngapekida a kodlas o, a pan kamela pein i, pwe a kiki ong, me salidi ko me pitila.',
        28: 'A Paulus kapitie laudeda masani: Kom der kame uk ala, pwe kit karos mia.',
        29: 'A ap idok lamp eu o tang rerer o dairukedi sang Paulus o Silas.',
        30: 'O wa ira wei sang indada: Maing ko, da me i en wiada, pwen kamaurela?',
        31: 'Ira ap masani: Poson Kaun Iesus, a koe o toun im om pan maurela.',
        32: 'Ira ari kawewe ong i o toun im a karos masan en Kaun o.',
        33: 'I ari uk ira ni auer ota ni pong o, widen ara pwal oko. I o na kan karos ap madang paptaiselar.',
        34: 'I ap kalua wong ira nan im a, ap kida mo’ra kisin manga, o peren kidar a posonla Kot, i o iang a kan.',
        35: 'A lao ran pasang, saupeidi ko poronela papa ko indada: Lapwada aramas pukat!',
        36: 'Silepan imateng o ap kaireki Paulus masan pukat indada: Saupeidi ko me ilakido, koma en lapwada. Koma ari kotila popol',
        37: 'A Paulus kotin masani ong irail: Irail sansal kadeike kit adar o woki kit men Rom, ap kase kit ale nan imateng, a met re men kadar kit ala so sansal. A so, irail en pein kodo, wa kit wei.',
        38: 'A papa ko kaireki saupeidi kan masan pukat. Irail ap masakadar ni ar rongadar, me ira men Rom.',
        39: 'Irail ari kodo, poeki re’ra o wa ira la sang, o ngidingideki ira, en sapal wei sang nan kanim o.',
        40: 'Ira ari pedoido sang nan imateng o, ap kotila ren Lidia. Ira lao tu ong saulang kan, ap panaui irail o sipale wei.',
    },
    17: {
        1: 'IRA kotin weid nan Ampipolis o Apolonia, ap pwara dong Tesalonik, wasa sinakoke en Sus oko mi ia.',
        2: 'Paulus ap kotilong ong re’rail duen a kin wiawia o iang ir kapakaparok pena sang kisin likau kan ni ran en sapat silu.',
        3: 'A kotin padaki o kasaleda, me Kristus udan kalokolok o iasada sang ren me melar akan, o me Iesus men et, me i kawewe ong komail, me Kristus.',
        4: 'O akai irail me posonla ap waroki ong Paulus i Silas, o pil men Krik lelapok me toto, o li saupeidi me kaidin me malaulau.',
        5: 'A Sus oko pepeirindar, ap ukada ol sued kai, o kapokon irail pena o kapeida kanim o, o kapil pena im en Iason, pwen wa ira dong pokon o.',
        6: 'Irail lao so diar ira da re ap waikelong dong saumas akan en kanim o Iason o saulang kai indada: Mepukat kamokimokidadar sappa, nan ira pil pwara dor met.',
        7: 'A Iason kasamo ira er, o irail karos kin tiakedi masan en Sisa ni ar katitiki, me dene amen Nanmarki Iesus.',
        8: 'Irail ari kamakaradar aramas o saumas akan nan kanim o ni ar rongadar mepukat.',
        9: 'Irail lao aleer sang ren Iason o me tei kan ar kapwa, re ap kadar ira la.',
        10: 'A saulang kan madang kadarala Paulus i Silas ni pong Peröa. Irail lao pwarado, ap kotilong ong nan sinakoke en Sus oko.',
        11: 'Mepukat me mau sang irail nan Tesalonik, pwe re pitipit aleer masan o pereperen kalelapokki kisin likau ni ran karos, ma melel mepukat.',
        12: 'Ari, me toto irail posonlar, li o ol en Krik kan kisan saupeidi me toto iang.',
        13: 'A men Sus en Tesalonik ko lao ronger, me Paulus pil padapadak nan Peröa masan en Kot, irail ap kodo o kamakaradar aramas akan.',
        14: 'A saulang kan madang kadarala Paulus, dene a pan kotidila ni oror. A Silas i Timoteus mimieta wasa o.',
        15: 'O me pelikid Paulus akan kalua i lel Aten. Irail lao aleer kusoned ong Silas o Timoteus, me ira en pitipit ko dong i, re ap samalar.',
        16: 'A ni en Paulus a kotin auiaui ira nan Aten kupura ap ola ni a masani nan kanim o dikedik en ani rok ia.',
        17: 'I ari kotin padaki ong Sus oko o me toun kaudok kan nan sinakoke pil wasan net, me a kotin padaki ong, me kin pokon pena wasa o ni ran akan karos.',
        18: 'A saunpadak en Epikurios o Stoik kai ap akamai ong i o akai indada: Da paupaulap men et men inda? O akai indada: Likamata i saunpadak en kot en wai akan aki a padaki ong irail rongamau en Iesus o en aramas ar pan maureda.',
        19: 'Irail ari ukada i o walang Areopak indada: Kit sota pan kak rong duen padak kap pot et, me koe kin kaweweda?',
        20: 'Pwe kasoi en wai pot, me kom wa dong kit, kit ari men weweki duen mepukat.',
        21: 'Pwe toun Aten o men wai kan, me mi wasa o, kin sopisokki ar kasokasoi o rongerong duen meakaros me kap.',
        22: 'A Paulus kotida pon dol en mars masani: Komail ol oko en Aten, i kasauiadar, me komail kin masak kaualap kot likam akan,',
        23: 'Pwe ni ai koko sili met, o kilekilanger omail saraui kan, i ap diaradar pei saraui eu, me intingidier poa: Sapwilim en kot me so diarokadar, me komail kin kaudoki ong ap sasa i, i me i kin padapadaki ong komail.',
        24: 'Kot me kotin wiadar sappa o audepa karos i me Kaun en nanlang o sappa, nan a sota kotikot nan im en kaudok kan me aramas wiadar.',
        25: 'O sota me kin upaki i pa en aramas likamata a kotin anane meakot; pwe pein i kin kotin nene ong karos maur, o asingok o meakaros.',
        26: 'O a kotin wiadar wein aramas en sappa karos kaparapar sang nta ta ieu, pwen kaukauson nan sap karos, o a kotin kileledier warai o wasan ar kauson.',
        27: 'Pwe ren raparapaki Kot, ma ir kak pam o diar i, pwe a sota kin doo sang amen amen kitail.',
        28: 'Pwe i me kitail kin memaureki, o mokideki, o mimiaki, duen akai omail saunkaul pil indadar: Pwe kis a kitail karos.',
        29: 'Ari, ma kitail kisan Kot, kitail ender lamelame, me Kot rasong kold, de silper, de takai, de dikedik eu, me aramas lolekong diaradar.',
        30: 'Ari, kot kotin kanongama ong kitail ni ansaun atail rotorot. A ansau wet a kotin masani ong aramas karos, ren kalula wasa karos.',
        31: 'Pwe a kotin kileledier ran eu, me a pan kotin kadeika kida sappa Ol amen, me a kotin katororedar ni tiak pung. A iet kilel, me a kotiki ong aramas karos: A kotin kaiasadar i sang ren me melar akan.',
        32: 'Irail lao rongadar duen mauredan me melar akan akai ap lalaue, a akai inda: Se men pur ong rong sang komui duen met.',
        33: 'Paulus ari kotila sang re’rail.',
        34: 'A ol akai waroki ong i o posonlar. Amen ir Dionisius kisan saunkapung kan; a li amen, me ad a Damaris, o pil akai iang irail.',
    },
    18: {
        1: 'MURIN mepukat a kotila sang Aten o kotilang Korint,',
        2: 'A lao diaradar Sus amen me ad a Akwila me ipwidier Pontus, me apton kodo sang Italien o a paud Prisila, aki Klaudius masani, me Sus oko karos en kokoke sang Rom, i ari kotilang re’ra.',
        3: 'O kotikot re’ra, iang dodok, pwe ira song ta ieu wiada im likau.',
        4: 'O ni ran en sapat karos a kin kotin padapadak nan sinakoke o kalekalolekonge men Sus o men Krik kan.',
        5: 'A Silas o Timoteus lao kodido sang Masetonien, Paulus kotin sopisokki kaualap padak o, pwe a kadede ong Sus akan, me Iesus me Kristus.',
        6: 'A irail lao akamai o lalaue, a ap sipededi sapwilim a likau masani ong irail: Dip omail en kapokon ong pein komail. Ngai me makelekel sang met, i pan kola ren men liki kan.',
        7: 'I ari kotila sang wasa o ap kotilang nan im en amen me ad a Sust me kin kaudok ong Kot, me im a pat ong sinakoke.',
        8: 'A Krispus, saumas en sinakoke posonla Kaun o, iangaki karos toun im a; toun Korint me toto lao rongada, ap posonla o paptaisela.',
        9: 'Kaun o ap kotin masani ong Paulus ni a auramen ni pong: Der masak, padapadak ender nenenla!',
        10: 'Pwe Ngai iang uk, o sota me pan sair uk, pwen kame uk, pwe nai aramas me toto nan kanim wet.',
        11: 'I ari kotikot wasa o par eu o saunipong wonu kaweweda masan en Kot nan pung arail.',
        12: 'Ni muein Kalion kakaundar Akaia, Sus akan ap wiaki eu, saikidi Paulus o wa dong i mon mol en kadeik o,',
        13: 'Indada: Lap men et kin pitipiti aramas, ren kaudok ong Kot ap palian kapung.',
        14: 'Paulus lao men masanda, Kalion ap masani ong Sus oko: Komail Sus oko, ma sapung eu de me sued kot, i pan rong komail.',
        15: 'A ma akamai duen lamalam, o ad akan, o omail kapung, nan pein komail pan wia, pwe ngai sota men saunkapung pan mepukat.',
        16: 'I ari siken ir wei sang ni mol en kadeik o.',
        17: 'A karos ap saikidi Sostenes, saumas en sinakoke o woki i mon mol en kadeik o. A Kalion sota insenoki mepukat karos.',
        18: 'Paulus lao kotikot wasa o ran toto, ap kotin kamurimuri ong saulang kan o iangala sop pot kotilang Sirien; Prisila i Akwila iang i. Mas a kotin kotedar tapwi nan Kenkräa, pwe a inau mia.',
        19: 'I ari supi ong Episus, pwilikidi ong ira wasa o, a pein i kotilong ong nan sinakoke o kaparok ong Sus oko.',
        20: 'Irail poeki i, en mimieta re’rail ansau warai, a sota kotin duki ong.',
        21: 'O a kotin kamurimuri ong irail masani: I udan iang kamadip kokodo nan Ierusalem. A ma Kot pan kotin mueid ong ia, i pan pure dong komail. A ap kotin masel sang Episus.',
        22: 'A lao kotin keredi Säsarea, ap kotidala ranamau ong momodisou ap kotilang Antiokien.',
        23: 'A kotikot wasa o ansau kis, ap kotila kakan sili nan wein Kalatia, o Prikien, kakelada tounpadak kan karos.',
        24: 'A men Sus amen, me ad a Apolus, me tikidar Aleksandrien, iei ol kadek lokaia, o me ereki kisin likau kan, a ko dong Episus.',
        25: 'Men et aleer padak ni al en Kaun o, o a kelail ni ngen e, a padapadak o kaweweda mau meakan duen Iesus; a paptais en Ioanes me a asa.',
        26: 'I ari tapiada aima padapadak nan sinakoke. A Akwila o Prisila lao rong i, ap uke dong ira i, kawewe ong i al en Kot.',
        27: 'A lao men kola Akaia, saulang kai ap inting wong tounpadak kan, poeki re’rail, ren kasamo i. I lao pwarado, ap sauasa irail, me poson kilar mak en Kot.',
        28: 'Pwe a manaman ong Sus akan, kasale ong irail sang kisin likau kan me Iesus me Kristus.',
    },
    19: {
        1: 'A ni ansau Apolus mi Korint, Paulus kotin kakan sili sap en pali poa kan, ap lele dong Episus wasa a diarada tounpadak kai.',
        2: 'A kotin masani ong irail: Komail aleer Ngen saraui ni omail posonlar? Irail potoan ong i: Se sota man rong, me Ngen saraui mia.',
        3: 'A ap kotin masani: A is, me komail paptais ong? Irail inda: Ong paptais en Ioanes.',
        4: 'Paulus masani: Ioanes paptais ki paptais en kalula, ni a masani ong aramas akan, me ren poson i me pan pwarado mur i, i Iesus.',
        5: 'Irail lao rongadar met, re ap paptais ong mar en Kaun Iesus.',
        6: 'Paulus lao kotin pwil po’rail lim a kan, Ngen saraui ap kotidi po’rail, irail ari lokaia ngil toror pasang o deideikop.',
        7: 'A ir ol oko me ekriamen.',
        8: 'I ari kotin purepure nan sinakoke o aima padapadak saunipong silu, kapakaparok o kawewedar meakan duen wein Kot.',
        9: 'A akai lao kapitakailar, o so poson, o lokelokaia sued ong aramas akan duen lamalam, a ap saupei sang irail o katorela tounpadak kan, o padapadaki ong irail nan im en padak en Tiranus',
        10: 'Mepukat wiauier saunpar riau; toun Asien karos ari rongada masan en Kaun o, men Sus o men Krik karos.',
        11: 'O Kot me kotin wia kida lim en Paulus manaman kapuriamui akan.',
        12: 'Re pil aleer lim en pudo o likau moa sang pali war a, pwilikidi ong me somau kan, somau o ap sare sang, o ngen sued akan keredi sang.',
        13: 'Men Sus widingok kai, me kin koko sili kati ani, ap song sakaraki dong irail, me tanwar en ngen sued kai, mar en Kaun Iesus, indada: Kit kaukilang komail Iesus, me Paulus kin padapadak due.',
        14: 'A ol isimen mia nain samaro lapalap Skepas, ol en Sus amen, me wiadar mepukat.',
        15: 'A ngen sued sapeng irail indada: I asa Iesus, o i asa duen Paulus, a komail, is komail?',
        16: 'A aramas o, me ngen sued mi poa, ap luse dong irail o kaloe irail edi. Ir ari tanga sang nan im o kiliso o kili olar.',
        17: 'A met lok sili ren men Sus o Krik akan, me kauson Episus. O masak kipa irail edi, o mar en Kaun Iesus me lomuinlar kaualap.',
        18: 'O me iang posonlar me toto kodo weokadar o kasaledar arail wiawia kan.',
        19: 'O pil me toto, me kati ani, wa pena nairail puk o isik ir ada mon karos; ir ari wadok pwain ar o diar, me a dok ong moni limenen.',
        20: 'Masan en Kaun ari pwaidar kaualap.',
        21: 'Murin mepukat Paulus ap kotin inong iong ni ngen e kakan sili wein Masetonien o Akaia, ap kotilang Ierusalem masanidar: I lao milar wasa o, i pil pan kilang Rom.',
        22: 'I ari kadarala Masetonien riamen, kisan me papa i: Timoteus o Erastus. A pein i kotikoteta mas nan Asien.',
        23: 'I ansau me moromorong laud wiauier pweki lamalam.',
        24: 'Pwe amen, me ad a Demetrius, saunmata amen, me kin wiada im en kaudok silper kan ong Diana, me kare ong irail, me kin wiawiada, moni toto.',
        25: 'I ap kapokon irail pena o toun dodok en song ota indada: Maing ko, komail asa, me dodok wet meid kadepa ong kitail, pwe i me kitail kapwapwaki.',
        26: 'A komail kilekilang o rongerong, me Paulus men et kin kaloedi o kawukila aramas toto a kaidin nan Episus eta, pwe pil koren iong nan Asien pon, ni a kin padaki ong aramas akan, me dene kaidin irail kot akan, me wiaui pan pa en aramas akan.',
        27: 'Mepukat meid apwal ong kitail. Pwe kaidin atail dodok eta me pan kamala, pwe pil im kaudok en kot Diana lapalap o a lingan, me toun Asien o sappa karos kin kaudoki ong pan sorela.',
        28: 'Irail lao ronger mepukat, re ap makara kida kaualap o weriweradar indada: Meid lapalap Diana en men Episus!',
        29: 'A karos toun kanim o ap pingidar, wiaki eu, tangalang im en madong, tangaki Kaios o Aristarkus men Masetonien, me waroki ong Paulus oko.',
        30: 'A Paulus lao pan kotilong nan pokon o, tounpadak kan ap sota mueid ong i.',
        31: 'O saumas en Asien kai, me kompokepa kan, ilake dong i, panaui i, ender kotilang im en madong o.',
        32: 'Ari, akai wia eu song en lokaia, a akai eu, pwe pokon o pingidar. A me toto re’rail sasa karep en ar pokon pena.',
        33: 'Irail sikon sang nan pokon o Aleksander; Sus oko me sikonla i. A Aleksander olol ong irail, ap men sapeng pokon o.',
        34: 'Irail lao asa, me i kisan Sus oko, re ap wiaki eu weriwerada auer riau: Meid lapalap Diana en men Episus!',
        35: 'A sauninting en kanim o lao kadukiedi pokon o, ap indada: Komail ol oko en Episus, is aramas, me sasa, me kanim en men Episus kin kaukaudoki ong Diana lapalap o dikedik, me pupedi sang nanlang?',
        36: 'A ma sota, me pan kak kalikame mepukat, komail en nenenla o der wiada me sapung!',
        37: 'Pwe komail ukedo ol pukat, me sota kin kuliada im en kaudok o, pil sota lalaue omail kot li.',
        38: 'A ma Demetrius o iang a kan mauki meakot ren amen, kapung ap pan wiaui, pwe saunkapung kai mia, ren kapukapung re’rail.',
        39: 'A ma komail mauki eu song toror, i me pan kapungala nan kapung o.',
        40: 'Pwe kitail pan pukoki morong en ran wet, pwe sota karepen, me kitail en kapungki pokon wet ar tangatang pena.',
        41: 'A lao masani ong irail mepukat, ap kadar pasang pokon o.',
    },
    20: {
        1: 'MORONG lao dukedier, Paulus ap molipe pena tounpadak kan, ap kotin kamurimuri ong irail o kotila, pwen sailokelang Masetonien.',
        2: 'A lao kakan sili sap oko, o panapanaui irail kaualap, ap kotilang wein Krik.',
        3: 'A lao kotikot wasa o saunipong silu, ap men kotilang Sirien, ari so, a kotin pure dong Masetonien, pwe Sus oko masamasan i.',
        4: 'A iet akan, me likid i lel Asien: Sopater nain Pirus men Peröa, a Aristarkus o Sekundus men Tesalonik, a Kaius men Derpe, o Timoteus, o Tikikus, o Tropimus men Asien.',
        5: 'Mepukat tiong mas ap aui kit nan Troas.',
        6: 'Murin kamadip en prot somut se serok wei sang Pilipi, tangatangki ran limau kokola re’rail Troas, wasa se mimi ia ran isu.',
        7: 'A ni ran kaieu en wik, ni at pokon pena, pwen pilitiki pena prot, Paulus ap kotin padaki ong irail. A mandan ran o a pan samala. A kotin kawarailar a padak lao lel ailep en pong.',
        8: 'A lamp toto mi nan kokon poa, wasa se pokon pena ia.',
        9: 'A manakap amen, me ad a Eutikus, me momod nan wanimtuk, me mair kalikala. A ni en Paulus a padak warai, i ari mair kalikala melel, ap pupedi sang ni kasilu en kokon poa, o re pokada, a melar.',
        10: 'A Paulus me kotidi kipedi ong poa o polodi i masani: Komail der mauk, pwe a memaur!',
        11: 'I lao kotidala o pilitiki pena prot, o konoter, o padapadak warai lao lel wasa ran, ap kotilar.',
        12: 'A irail wado manakap memaur ap pereperen kaualap.',
        13: 'A kit me madang iang sop o, tangatang kolang Asos, wasa se pan uk ia Paulus, pwe i me a kakalik ong kit. A pein i pan sapal.',
        14: 'A lao tu ong kit nan Asos, se ap uk i, tangalang Mitelene.',
        15: 'Kit tangatang kodo sang wasa o, a manda se lel ong likin Kios, o manda se lele dong Samos, o se mondi Trokilion, a manda se pwara dong Miletus.',
        16: 'Pwe Paulus kileledier en dauli Episus, pwe a der pwapwand nan Asien, pwe a kotin karawaru, ma a pan kak, a pan lel ong Ierusalem ni ran en Pentikos.',
        17: 'A sang Miletus a kotin ilakilang Episus molipe saunkoa en momodisou kan.',
        18: 'Irail lao pwara dong i, a kotin masani ong irail: Komail asa duen ai wiawia re omail ansau karos sang ni tapin ran o, me i lel Asien,',
        19: 'Duen i papa Kaun o ni aktikitik, o sangesang, o kamekam nan pung en Sus oko, ni ar rukiruki ia di.',
        20: 'O duen i sota oki sanger meakot me katepan, pwe i kaireki komail karos, o padapadaki komail sansal o nan im akan.',
        21: 'O i kadede ong men Sus o pil men Krik kalula ong Kot o poson atail Kaun Iesus Kristus.',
        22: 'A kilang, i ap kokodalang Ierusalem, ngen i salidi o i sasa, da me pan pid ia wasa o.',
        23: 'A Ngen saraui kin kotin kadede ong ia nan kanim karos, me sal akan o kamekam kin auiaui ia.',
        24: 'Ari so, i sota kin insenoki mepukat, i pil sota kasampwaleki maur i, pwe i en kaimwisokela ai koa dodok, me i aleer sang ren Kaun Iesus, en kadede rongamau en mak en Kot.',
        25: 'A kilang, i ap asaer, me komail karos, me i padapadaki onger wein Kot, pan solar udial mas ai.',
        26: 'I me i kadede ong komail ran wet, me i makelekel sang ntan komail karos.',
        27: 'Pwe i padaki ong komail duen kupur en Kot, o sota man meakot me i okisang komail.',
        28: 'Komail ari kalaka komail o momodisou karos wasa, me Ngen saraui kotin kasapwil komail dang silepa ko, pwen apapwali momodisou en Kot me a kotin pwainiki pein nta.',
        29: 'Pwe i asaer, me murin ai samalar kidi komad akai pan pwara dong komail, me sota pan kasampwaleki pwin o.',
        30: 'A ol akai pan uda sang nan pein komail, me pan padak sapung, pwen wiaki tounpadak kan pein ar warok kan.',
        31: 'Komail ari masamasan o tamanda, me i sota dukedi, panaui amen amen, sangesang ni ran ni pong saunpar silu.',
        32: 'Ari, i pan mueid ong komail Kot o masan en kupur a, me manaman ong kapwai komail ada, o kotiki ong komail soso eu ren me saraui kan.',
        33: 'I sota noroke en amen a silper, de kold, de likau.',
        34: 'Pein komail asa, me pa i kat kin papa ia o ai warok kan.',
        35: 'I kasale ong komail er meakan duen komail en dodok, pwen sauasa me luet akan o tamatamanda masan en Kaun Iesus akan, duen a pein kotin masani: Kiki wei me kaperen sang ale.',
        36: 'A lao kotin masanier mepukat, a kelepuki iang irail karos kapakap.',
        37: 'Irail ari sangesang kaualap o polodi tapin wor en Paulus o metik i.',
        38: 'Re insensuedekier kaualap a masan, me dene re solar pan udial silang i. Irail ari likid i koti ong pon sop o.',
    },
    21: {
        1: 'KADEKADEO kit lao maselwei sang murin at kamurimuri ong irail se tangatang inen wong Kus, a manda lel ong Rodus, a sang wasa o se tangalang Patara.',
        2: 'Kit lao diaradar sop pot, me pan kola Pönisien, se ap keredang poa maselwei.',
        3: 'Kit lao kilanger Sipern, se dauli ni pali maun, tangatang kolang Sirien ap supi ong Tirus, pwe i wasa audepan sop o pan pwilidi ia.',
        4: 'Se lao diaradar tounpadak kan, kit ap mimieta wasa o ran isu. Irail ap masanki Ngen, Paulus ender kodalang Ierusalem.',
        5: 'Kadekadeo kit lao kaimwisokila ran oko, se ap masel kokola. Irail karos me likid kit lel likin kanim, li o seri kan pil iang; kit ap kelepuki ni oror, o kapakap.',
        6: 'Kit lao kamurimur pena, se ap kereda pon sop o, a irail purelang deu’rail.',
        7: 'Kit tangatang kodo sang Tirus ap ko dong Ptolomais; kit ap ranamaui saulang kan o kairu re’rail ran eu.',
        8: 'A mandan ran o se maseler, ap lel ong Säsarea, kit ap pedelong ong nan im en saunpadak Pilipus, me kisan isimen oko, o mimieta re a.',
        9: 'A men et na seripein makelekel pamen mia, me kin deideikop.',
        10: 'A ni at kaukauson wasa o ran toto, saukop amen ap kodido sang Iudäa, me ad a Akapus.',
        11: 'A lao pwara dong kit, ap ale sapwilim en Paulus pirapir pira pena pein pa a o nä a kan, katitiki: Iet me Ngen saraui kotin masani: Iet duen men Sus oko, me mi Ierusalem, pan saliedi ol o, me a pirapir wet, o pangalang i nan pa en men liki kan.',
        12: 'Kit lao rongada mepukat, kit o pil irail karos toun wasa o ap poekipoeki a ender kotidalang Ierusalem.',
        13: 'A Paulus kotin sapeng: Da me komail sangesangki o kawekila nan mongiong i? Pwe kaidin salidi eta, me i kak ong, pwe pil mela nan Ierusalem pweki mar en Kaun Iesus.',
        14: 'A lao sota duki ong, kit ap nenenla indada: Kupur en Kaun o en pwaida.',
        15: 'Murin ran pukat se ki pena at kapwa kan o daululang Ierusalem.',
        16: 'A tounpadak en Säsarea kai pil iang kit, o re ukado Mnason men Sipern, tounpadak ma amen, me se pan kairu re a.',
        17: 'Kit lao lel Ierusalem, saulang kan kasamo kit popol.',
        18: 'A mandan ran o Paulus iang kit kotila ren Iakopus o saunkoa karos pokon pena wasa o.',
        19: 'A lao ranmaui irail, ap kotin kasokasoia meakan, me Kot kotin wiai ong men liki kan ki a dodok.',
        20: 'Irail lao rongadar mepukat, re ap kapingaki Kot indai ong i: Ri at, kilang men Sus me totoia me iang posonlar, o irail karos kin kasampwaleki kapung o.',
        21: 'Nan a loki ong irail duen komui, me dene komui kin kaukawewe men Sus, me dondole men liki kan, ren kasela Moses o padapadaki, re ender sirkomsais seri kan, o pil der dadaur tiak kan.',
        22: 'A iaduen, pokon pan wiaui, o re pan rongada, me komui samador.',
        23: 'Ari, komui pan wiada met, me se pan indai ong komui: Ol pamen mi re at, me ar inau mia.',
        24: 'Uk irail ada o kamakelekel komui da iangaki irail, o pwain irail pwe mong arail en seisei, o karos pan kilang, me likam pot, me re ronger duen komui, o me komui pil kin kapwaiada kapung o.',
        25: 'A duen me posonlar sang ren men liki kan, se intingiedier o kusoned edar, me ren der kapwaiada mepukat. A iet eta: Ren liki sang uduk me mairong ong kot likam, o nta, o man mopelar, o nenek.',
        26: 'Paulus ap kotin ukada ol oko, a manda a kamakelekelada pein i ap iang irail kotilong ong nan im en kaudok o kotin kasaledar ran en arail kamakelekel, lel mairong en amen amen wiauier.',
        27: 'A ran isu lao koren iong nikier, men Sus en Asien ap kilanger i nan im en kaudok o, rap kamoromoroda aramas karos o saikidi i,',
        28: 'Weriwerada indada: Ol en Israel, komail sauasa, iet aramas o me kin kaukawewe ong karos wasa karos, ren palian Sus akan, o kapung, o wasa kis et, o a pil kalua dong nan im en kaudok men Krik kai, o kasaminela wasa saraui wet.',
        29: 'Pwe mas o re kilangadar, me Tropimus men Episus iang i nan kanim o, re ap kiki ong, me Paulus kalualong ong i nan im en kaudok.',
        30: 'A kanim o moromorongada kaualap o aramas akan tang pena. Re ap saikidi Paulus o waike sang i nan im en kaudok o, a wanim ko ap madang ritidi.',
        31: 'Irail pan kamela i, a rong ap lel ong saumas en saunpei kan, me Ierusalem moromorongda.',
        32: 'I ari madang ukada saunpei o saumas akai ap tangadi wong irail. Ir lao kilang saumas o saunpei ko, re ap solar woki Paulus.',
        33: 'Saumas o ap kai ong, koledi i masani, i en salikidi sal mata riapot, o idok: Is i, o da me a wiadar?',
        34: 'A akai sang nan pokon o weriwer wiada eu song en lokaia a akai eu. A ni a sota kak weweki, me re moromorongki, ap masani, a en wisikelang nan im en saunpei.',
        35: 'A lao lel ong kandake o, saunpei ap wewa i, pweki pokon o koiden pena i.',
        36: 'Pwe pokon o, me idauen, weriwer indada: Siken wei i!',
        37: 'A ni en Paulus a pan wisikelong ong nan im en saunpei, a ap masani ong kaun lapalap o: A sota muei ong ia, en indang komui meakot? A ap masani: Komui asa lokaia en Krik?',
        38: 'Ari, kaidin komui ol en Äkipten, me kapeida aramas oko mon ran akai, ap kalualang sap tan ol lolap pakid?',
        39: 'A Paulus masani: Ngai ol en Sus amen, men Tarsus, kanim indand en Silisia eu, i men poeki re omui, en mueid ong ia, en kapakaparok ong aramas pukat.',
        40: 'I ari mueid ong i. Paulus ap kotida pon kandake o olol ong aramas akan. A lao molelar kaualap, Paulus ap kaparok ong irail ni ngor en Ipru masani:',
    },
    22: {
        1: 'RI ai ko, sam ai ko komail, rong mas ai sapeng komail.',
        2: 'Irail lao ronger, me a masani ong irail ni lokaia en Ipru, re ap nenenla kaualap. I ari kotin masani.',
        3: 'Ol en Sus amen ngai, me tikidar Tarsus en Silisia, a i kakairida nan kanim wet ni aluwilu en Kamaliel, padapadakki kapung en sam atail akan, o nantiong pongipongi Kot dueta komail kin wia ran wet.',
        4: 'O i kawelar al pot et lel ong kamelar aramas, ni ai saliedi o pangalang imateng ol o li akan.',
        5: 'Pwe iduen me samero lapalap o saumas akan kin kadede kin ia, pwe i aleer sang irail kisin likau, ong ri (atail) akan. I ap kolang Damaskus, pwen pil saliedi o wa dong Ierusalem, me mi wasa o, pwe ren kamekame.',
        6: 'A ni ai koko wei korendor Damaskus, nin sauas, marain eu kodido sang nanlang, sare ia da.',
        7: 'Ngai ari pupedi nani pwel o rongada ngil eu, me masani ong ia: Saul, Saul, da me koe kame kin ia?',
        8: 'Ngai ari potoan ong: Is komui Maing? A kotin masani ong ia: Ngai Iesus en Nasaret, me koe kin kame.',
        9: 'A me iang ia udialer marain o, ap masapwekadar, a re sota rong kapit en me masan dong ia.',
        10: 'Ngai potoan ong: Da me i en wiada Maing? Kaun o ap kotin masani ong ia: Paurida u kowei ong Damaskus, nan a pan kapare ong uk wasa o, me kaonop ong uk er, en wiada.',
        11: 'A i solar kak kilang wasa, aki lingan en marain o, i ap daululang Damaskus; me iang ia kalua kin ia pa i.',
        12: 'Ananias, ol lelapok amen duen kapung o, me kalok mau sili ren Sus akan karos, me kauson wasa o,',
        13: 'Ap ko dong ia kasikasinen imp ai indai ong ia: Ri ai Saulus, kilangada wasa! Ari, ni auer ota i saradang i.',
        14: 'I ari katitiki: Kot en sam atail akan, me pil uk adar, pwe koe en lolekongki a kupur, o udial me Pung o, o rong kapit en silang i.',
        15: 'Pwe koe pan sapwilim a saunkadede ong aramas karos, duen me koe kilangadar o rongadar.',
        16: 'Ari, da me koe auiaui? Paurida o paptaisela, pwe dip om akan en widen sang, o sakarkidang mar a.',
        17: 'A kadekadeo i lao pwara dong Ierusalem o kapakap nan im en kaudok o, i ap wukilar.',
        18: 'O i kilang i, me kotin masani ong ia: Kanangata, madanga wei sang Ierusalem, pwe irail sota pang duki ong om kadede kin ia.',
        19: 'Ngai ari potoan ong: Maing, pein irail asa, me i pangalang nan imateng o woki nan sinakoke kan me kin poson komui.',
        20: 'A ni sapwilim ar saunkadede Stepanus kamatalar, ngai pil u impa o peren kidar a kamatalar, nekinekid likau en me kamatalar i ko.',
        21: 'A ap kotin masani ong ia: U ko wei, pwe I pan kadar uk ala wasa doo ren men liki kan.',
        22: 'Irail rongerong i lel ong masan pot et, ap ngil laudeda indada: Siken wei sang sappa lap men et! Pwe a sota mau ong, i en memaureta!',
        23: 'A ni arail weriwerada, o kaselar ar likau, o kasadar pwel par,',
        24: 'Kaun lapalap o ap masani, i en wisikelang nan im en saunpei o masani, ren woki i, pwe i en lelapok kila, da me re weiweilokeki i.',
        25: 'Irail lao saliedi i, Paulus ap idok ren kaun o, me u impa: Me pung, en woki aramas en Rom amen, me kaikenta pakadeikadar?',
        26: 'Kaun o lao rongada met, ap kola ren kaun lapalap o indada: Da me kom pan wiada, pwe aramas men et men Rom amen.',
        27: 'Kaun lapalap o ap kodo indai ong i: Katitiki ong ia, ol en Rom amen komui? A sapeng: Ei.',
        28: 'Kaun lapalap o sapeng: Pwai laud me i saladok kilar. A Paulus masani: A ngai me tikidar saladok.',
        29: 'Me kodo kadeikada i, ap madang pure sang i, o kaun lapalap lao asadar, me i ol en Rom amen, a pil masakadar, pweki a saliedi i.',
        30: 'A mandan ran o a inong iong melel asa karep en Sus oko ar pangala i, ap lapwada i o kapokon pena samero lapalap o toun kapung o, ap wadila Paulus o kotikidi ong i mo’rail.',
    },
    23: {
        1: 'A PAULUS kotin aupwil sili nan kapung o ap masani: Ri ai ko, i dadaurata me mau ong Kot lao lel ran wet.',
        2: 'A samero lapalap Ananias masani ong men impa, ren pikir au a.',
        3: 'Paulus ap masani ong i: Kot pan kotin pikir uk malaun men koe, pwe koe momod wasa en, en kadeik ia da duen kapung o, ap tiakedi kapung o ni om indada, ren pikir ia.',
        4: 'A men impa indada: Koe pan lalaue sapwilim en Kot a samero lapalap?',
        5: 'Paulus ap masanier: Ri ai ko, i sasa, me i samero lapalap o, pwe a intingidier: Koe der nan au sued duen omail kaun lapalap o!',
        6: 'A Paulus lao diaradar, me akai irail Sadusär, a akai Parisär, ap kapitie laud nan kapung o masani: Ri ai ko, ngai Parisär amen o nain Parisär amen, ai kaporopor en me melar akan ar pan maureda, i me i pan pakadeikada.',
        7: 'A lao masanier met, Parisär o Sadusär akan ap akamai pena; ari momod o muei pasang.',
        8: 'Pwe Sadusär kin inda, me dene sota me pan maureda, o pil dene sota tounlang, pil so ngen, a Parisär kin kamelele karos.',
        9: 'A weriwer laud wiauier. A saunkawewe kan, me kisan Parisär kasinenda kaparok katitiki: Sota me sued kot en aramas men et, me se diar. A ma ngen eu de tounlang amen masani ong i, kitail der palian Kot!',
        10: 'A lao moromorong kaualap, kaun lapalap o ap masak, me Paulus pan dapenok pasang, ap masani, me saunpei kai en kodilan koledi i, wado sang nan pung ar o wa dong nan im en saunpei.',
        11: 'A pong pena sang ran o kaun o kotikot re a masani: Kaporopor mau, pwe duen om kadede ia nan Ierusalem, iduen koe pil pan kadede ia nan Rom.',
        12: 'A lao ran pasang, Sus akai ap inauki pena o kaukila, me re pan solar kang o nim meakot, re lao kamelar Paulus.',
        13: 'A irail, me wiadar inau wet, me paek sama.',
        14: 'Irail kodo ren samero lapalap o saumas akan katitiki: Se inauki pena o kaukila, me se solar pan kang o nim meakot, se lao kamelar Paulus.',
        15: 'Komail o toun kapung ari poeki ren kaun lapalap o, a en kadara dong komail i. Dene komail pan raparapaki melel re a, a kit pan masamasan kamela i, mon a pan pwara dong komail.',
        16: 'A wawan Paulus seri amen lao ronger ar ruki i, ap pedelong ong im en saunpei kai kaireki Paulus.',
        17: 'Paulus ap ekeredo kaun amen, masani ong i: Kare wong manakap men et ren kaun lapalap o, pwe meakot mia, me a men kaireki i.',
        18: 'I ari ukada i kare wong i ren kaun lapalap o indada: Paulus me salidi, eker ia dong i o poeki re i, i en wa dong komui manakap men et, pwe meakot mia, me a men kaire kin komui.',
        19: 'Kaun lapalap ap koledi pa a o koieila wasa rir kalelapok: Da me koe men kaire kin ia?',
        20: 'I ari katitiki: Sus akai inauki pena, en poeki re omui, en kadara dong kapung Paulus lakap, dene komui men pur ong raparapaki mau due.',
        21: 'A komui der duki ong irail, pwe ol paek sama, me rukiruki i, me inauki pena o kaukilar, me re solar pan kang o nim re lao kamela i. A irail auiaui ansau wet, me komui en mueid ong irail i.',
        22: 'Kaun lapalap o ap kadarala manakap o masani ong i: Der indang meamen, me koe kaire kin ia met!',
        23: 'A lao ekeredor kaun riamen, ap masani: Kaonopada saunpei riepuki, pwen kola Säsarea, o pil me dake os isiakan, o me wa katieu riepuki sang ni klok duau en pongpong wet.',
        24: 'O pil kaonopada man akai, me re en kida poa Paulus, o ren kanakanai ong walang i ren kopina Peliks.',
        25: 'A pil intingiedier kisin likau duen met:',
        26: 'Ngai Klaudius Lisias kadar wong komui maing kopina Peliks ai ranamau.',
        27: 'Ol men et, me Sus oko saikidier, o metar kis a pan kamela re’rail. A ngai ukada saunpei kei dorela i ni ai rongada, me i men Rom amen.',
        28: 'A ni ai men kalelapok, da me re weiweilokedi i, i ap wadila ren ar kapung o.',
        29: 'Ngai ari diaradar, me a pangpangala pweki peidok en ar kapung. A sota me i diar, me a pun kak kame kila de salikidi.',
        30: 'I lao asadar, me Sus oko rukiruki ol o, i ap madang kadar wong komui i, o i kakaliki ong me pangala i kai, en kaireki wong komui duen i. Ran kaselel!',
        31: 'Saunpei ko ap ukada Paulus kalua i Antipatris ni pong o duen a kawad kin irail.',
        32: 'Mandan ran o re ki ong me dake os akan, ren wala i, ap purelang im en saunpei.',
        33: 'Mepukat lao lel ong Säsarea, ap ki ong kisin likau ren kopina, o pil kasale ong i Paulus.',
        34: 'A lao wadoker o idok, menia i, o mangier, me a kisan men Silisia, ap masani:',
        35: 'I pan rong uk, lao me pang uk ala pil pwarador. I ari masani, i en nekinek nan tanpas en Erodes.',
    },
    24: {
        1: 'A MURIN ran limau samero lapalap Ananias kotido iangaki saumas akai, o saunlokaia men, me ad a Tertulus; irail weiweiloke Paulus ren kopina.',
        2: 'A lao wisikedo, Tertulus ap pikikidi weiweiloke i indada:',
        3: 'Kit asaer duen muein popol re omui o duen kamau toto kan ong toun wei wet, pweki omui kalangan maing Peliks. O i me se kapikapinga kin komui ansau o wasa karos.',
        4: 'A i sota men kapangai komui, iet eta me i poeki re omui: Komui en kotin mangi kit duen omui kalangan.',
        5: 'Pwe se diaradar, me ol men et me morsued o me kin kapeida Sus akan karos, me mi sappa, o i me saumas en pwin likam en Nasaret,',
        6: 'Me pil song kasaminela im en kaudok o, i me se koledi i, pwen kadeikada, duen at kapung o.',
        7: 'A monsap Lisias kotin pwarado, kotiki sang i nan pa at ki a manaman lapalap,',
        8: 'Masani ong me weiweiloke i, en poto dong re omui, a komui lao kalekalelapok re irail, kom pan pein mangi duen meakan, me se pang kila i.',
        9: 'A Sus oko pil weiweiloke Paulus indada: Mepukat melel!',
        10: 'A kopina lao olol ong Paulus, en kaparok, a ap kotin sapeng masani: Ni ai asaer, me komui saunkapung pan toun wei wet saunpar toto, i peren kida, ai pan indinda duen pein ngai.',
        11: 'Pwe komui pan mangi, me pong ngaul ria pong eta, me i kodalang Ierusalem pwen kaudok.',
        12: 'A irail sota diar ia da lokaia ong amen nan im en kaudok, de kapeida aramas oko nan sinakoke kan de nan kanim o.',
        13: 'O re pil sota kak kadede, me re pang kin ia la met.',
        14: 'A iet eta, me i men kadede ong komui, ni ai kin kamelele karos, me intingidier nan saukop akan o kapung o, i kin kaudoki ong Kot en sam ai kan duen tiak en ir, me re kaadaneki pwin likam.',
        15: 'O i kaporoporeki Kot me irail pil kamelele me melar akan pan maureda, me pung o me sapung kan.',
        16: 'A i me i kin sosongki pein ngai, pwe lol i en pung mon Kot o aramas akan.',
        17: 'A murin par toto i kodon wa dong toun sap wet kisakis eu o wiadar mairong.',
        18: 'I ansau, me re diar ia makelekeladar nan im en kaudok o sota weriwer de moromorong.',
        19: 'A ir pukat Sus akai nan Asien menda re sota mi met mo’mui, kadede ngai, ma re diar me sued kot re i?',
        20: 'De mepukat en pein kasansaleda sapung da, me re diar re i ni ai mi mon kapung o.',
        21: 'A iet eta lepen lokaia, me i kida ni ai udar nan pung ar indada: En me melar akan ar pan maureda, i pan pakadeikki ran wet re omail.',
        22: 'A Peliks lao ereki mepukat, pwe a mangi mau duen al pot et, ap kasau ir wei masani: Kaun Lisias lao kotido, i ap pan kaimwisokela omail kapung.',
        23: 'I ap masani ong kaun en kolekol Paulus o kasaladokela i, o ender inapwiedi iang a kan, en kodon papa i.',
        24: 'A murin ran akai Peliks pwarado, a paud Drusila iang i, iei li en Sus amen, ap molipedo Paulus o karonge i duen lamalam en Kristus.',
        25: 'A ni a kapakaparok duen pung, o makelekel, o kadeik, me pan wiaui, Peliks ap masapwekadar o sapeng: U kowei ansau wet, i lao pisokalar, i pan eker uk do.',
        26: 'A pil kaporoporeki, me Paulus pan kotiki ong i moni, pwen lapwada i; i me a purepure ekeker kido i o kasokasoi ong i.',
        27: 'A murin par riau Porsius Pestus sapwiladar wiliandi Peliks. A Pelisk men konekon ren Sus oko, ap sota lapwada Paulus.',
    },
    25: {
        1: 'PESTUS lao pwarador nan wei, ap kotidalang Ierusalem sang Säsarea ni ran kasilu.',
        2: 'Samero lapalap o saumas akan en Sus oko ap pwara dong re a weiweiloke Paulus o poekipoeki re a,',
        3: 'O inong iong konekon re a, pwen palian Paulus, pwe a en wa dong Ierusalem i, a re masamasan i, pwen kamele ni a kotikot kodo.',
        4: 'A Pestus masani, me Paulus pan mimieta Säsarea, a pein i pan madang masel wei.',
        5: 'A me lapalap re omail pan kak iang ia kodila o kadede ol o, ma dip a mia.',
        6: 'A lao kotikot re’rail pong walu pong de ngaul, ap kotidilang Säsarea o mandan ran o a kaipokedi pon mol en kadeik o masani, Paulus en wisikedo.',
        7: 'A lao pwarador, Sus oko, me kodido sang Ierusalem, ap kapil pena i o kadipe i kaualap, ap sota kak kadededa.',
        8: 'Pwe Paulus kotin sapen masani duen pein i: I sota wiadar dipi ong kapung en Sus oko, de ong im en kaudok o, de ong Sisa.',
        9: 'A Pestus men konekon ren Sus oko, ap sapeng Paulus masani: Koe men kodalang Ierusalem, pwen pakadeikada re i wasa o?',
        10: 'A Paulus kotin masani: I mi mon mol en kadeik en Sisa, wasa me mau ong, i en pakadeikada. Sota me sapung eu, me i wiai ong Sus oko, duen me pein komui mangi.',
        11: 'Ma i wiadar sapung eu de meakot me warong kamela, i sota pan kang mela. A ma so melel, me mepukat kine kin ia, sota me pan kak pang ia lang irail. I dorolang Sisa!',
        12: 'Pestus lao kalelapok ren momod en kadeik o, ap masani: Koe dorolang Sisa, ari koe pan pwarala ren Sisa.',
        13: 'Murin ran akai nanmarki Akripa o Pernise koti dong Säsarea, pwen ranamau ong Pestus.',
        14: 'Ira lao kotikot wasa o pong toto, Pestus ap kaireki nanmarki duen Paulus masani: Ol sensal amen mi met, me Peliks saliedi ap samalar.',
        15: 'A samero lapalap o saumas en Sus akan kaire kin ia duen i ni ai potopot Ierusalem inong iong i en kadeikada i.',
        16: 'A ngai sapeng irail: Kaidin duen tiak en men Rom, en pangala aramas amen, en kamela, mon me pangala i kan saikenta sansal mo a, o a muei ong i er, en sapeng duen me re pang kila i.',
        17: 'Irail lao pokon dong met, a mandan ran o i madang mondi pon mol en kadeik o inda, ol o en wisikedo.',
        18: 'A me pangala i kan lao pwarado, re sota katitiki mesued kot, duen i kiki ong.',
        19: 'A akai peipeidok mia duen pein arail lamalam o duen ol mela amen me ad a Iesus, me Paulus kin inda, me dene a memaureta.',
        20: 'Ngai ari poneponeki duen mepukat, i ap idok re a, ma a sota men kodalang Ierusalem, pwen pakadeikada wasa o duen mepukat.',
        21: 'A Paulus lao dorolang kadeik en Aukustus, ngai ap inda, ren koledi i, i lao kadarala i ren Sisa.',
        22: 'Akripa ap masani ong Pestus: I pil men rongerong aramas o. A masani: Lakap kom pan rong i.',
        23: 'A mandan ran o Akripa i Pernise lao kotin pwarado ni ar kapwat lingan kaualap o kotilong ong nan im en kapung, o ol lapalap akan iangaki kaun en kanim o, Pestus ap masani, Paulus en wisikedo.',
        24: 'A Pestus masani: Maing nanmarki Akripa o komail ol akan karos, me iang kit kotikot wasa et, komail masani, pweki men et, Sus akan karos kin poekipoeki re i nan Ierusalem o pil met; ni ar palian i indada, me dene a sowar ong memaureta.',
        25: 'A i lao diarada, me sota me a wiadar, me war ong kamela o pein i dorolang Aukustus, ngai ap kileledier me i pan kadarala i.',
        26: 'A sota me i asa, en intingiedi wong nai saupeidi. I me i waki dong komail i, mo’mui ta maing nanmarki Akripa, pwe kapung lao nikier, i en asa, da me i en intingieki wei.',
        27: 'Pwe i lamelame, me sapung, en kadarala me salidi amen, ap sota kaireki duen karep en salidi.',
    },
    26: {
        1: 'AKRIPA ap masani ong Paulus: Koe me saladoklar en kapakaparok ki pein uk. Paulus ap kapa wei lim a, kadededar pein i:',
        2: 'I ap peren kidar maing nanmarki Akripa, me i pan kapakaparok mo’mui ran wet duen meakan, me Sus oko pang kin ia la,',
        3: 'Pwe komui me erekilar en Sus oko ar lamalam o peipeidok kan, i ap poeki re omui, en kotin kanongama mamangi ia.',
        4: 'Ai wiawia kan arain maur i, me tapida Ierusalem ren sau i kan, Sus akan karos asa due.',
        5: 'Irail me asa ia sang mas kokodo, ma re men kadede ia, me ngai kisan pwin kelail en at lamalam, me ad a Parisär.',
        6: 'Ngai ari mi mon kadeik, pweki ai kaporoporeki inau o, me Kot kotiki ong sam at akan.',
        7: 'Nan i inau o, me at kainok eisokriau kin kaporoporeki, me re pan pwaiki ong ar nantiong kaudok ong Kot ni ran o ni pong. Maing nanmarki Akripa iei kaporopor me i pang kila ren Sus oko.',
        8: 'Da me komail sota kamelele, me Kot kotin kaiasada me melar akan?',
        9: 'Mas o i kiki ong, me i en wiada meakan, me kaokaoe mar en Iesus en Nasaret.',
        10: 'I me i pil wiadar nan Ierusalem; o me saraui kan toto me i saliedier ong nan imateng murin ai aleer manaman sang ren samero lapalap akan o irail lao kamelar, ngai pil sauasa.',
        11: 'I kame irail pan pak toto nan sinakoke kan karos, o koidong ong irail, re en lalaue, o ngai lingarangar kaualap pa’rail; i kin kame irail lel ong kanim en wai kan.',
        12: 'A ni ai wiawia mepukat, o kokolang Damaskus ni manaman en samero lapalap,',
        13: 'Maing nanmarki, nin sauas i ap kilangadar nani al o marain eu sang nanlang, me lingan sang katipin, me sensereda imp ai o me iang ia kai.',
        14: 'Kit karos lao pupedier nani pwel, i ap rongadar ngil eu, katitiki ong ia ni lokaia en Ipru: Saul, Saul da me koe kamekame kin ia? Nan a pan apwal ong uk, en tametame tek o.',
        15: 'Ngai ari idok: Is komui Maing? Kaun o ap kotin masani: Ngai Iesus, me koe kin kame.',
        16: 'Koe ari paurida, kasinenda, pwe i me I pwaraki dong uk, pwen kasapwil uk ada, pwe koe en papa o saunkadede men en meakan, me koe kilangada, o meakan, me I pan kapwara dong uk.',
        17: 'O I pan dondoro sang uk ni pa en aramas akan o men liki kan me I pan kadar uk wei ong,',
        18: 'Pwen kapad pasang mas arail, pwe re en wuki sang rotorot, wuki ong marain, o sang ni manaman en Satan ong Kot, pwe re en lapwa sang dip ar akan, o ren ale ar soso ren me kamakelekele kidar poson.',
        19: 'Ari maing nanmarki Akripa, i sota sopeiki ong kasansal en nanlang o.',
        20: 'Pwe mas i padaki ong toun Damaskus o Ierusalem, o sap en Iudäa kan, o men liki kan, en kalula o wuki ong Kot, o kapwaiada wan kalula mau.',
        21: 'Nan i me Sus akan saik ia kidi nan im en kaudok o, o re song kame ia la.',
        22: 'Ari so, en Kot a kotin ieiang ia, me i mimieki lao lel ran wet, padapadaki me tikitik o me laud akan, o sota me i inda, i eta, me saukop akan o Moses pil masanier, me pan wiaui:',
        23: 'Ieteten, Kristus en kamekam, o me a pan men mas en me pan iasada sang ren me melar akan, o padaki ong toun wei o pil ong men liki kan duen marain o.',
        24: 'A ni a kapung kila mepukat, pein i Pestus ap ngil laudeda masani: Paulus, koe iakalar! Om sukusukul toto me kapwepwe uk adar.',
        25: 'A Paulus kotin masani: I sota iakalar maing isou Pestus, a i kin kida kasoi melel o pung.',
        26: 'Pwe nanmarki kotin mangi duen mepukat; i me i pil aima padapadakieki ong i, pwe i asa, sota meakot, me a sota kotin ereki, pwe kaidin wasa rir, me mepukat wiauier.',
        27: 'Nanmarki Akripa, komui poson saukop akan? I asa, me komui kin poson.',
        28: 'Akripa ap masani ong Paulus: Me tar kis, a komui pan kainong ong ia en saulangala.',
        29: 'Paulus masani: I ngongki ong Kot, me komui o karos, me rongerong ia ran wet, en dueta ngai, a iermen sal mata pot et.',
        30: 'Nanmarki, o kopina, o Pernise, o me iang irail kaipokedi wasa o, ap kotida,',
        31: 'O kelepala, ap kapakaparok nan pung ar mamasani: Aramas men et sota kin wiada me war ong kamela de salidi.',
        32: 'Akripa ap masani ong Pestus: Aramas men et pan lapwada, ma a sota dorolang Sisa.',
    },
    27: {
        1: 'A LAO kileledier, me se pan serokelang Italien, re kasilaki Paulus, o akai me salidi, kaun en saunpei amen, me ad a Iulius, kisan pwin en Aukustus.',
        2: 'Kit ari kereda pon sop en Adramitien pot, me pan supi ong kanim en Asien akan, me mi pon oror, ap tang wei. Ari, Aristarkus, men Masetonien amen sang Tesalonik iang kit.',
        3: 'Mandan ran o se leler Sidon. A Iulius me kadek ong Paulus, ap mueid ong i, en kotila ren kompokepa ko pwen kasarloleit.',
        4: 'Kit ari maselar sang wasa o, ap tangatang panangen Sipern, aki ang me u dong kit.',
        5: 'Kit tangatang kotela lepen sed en Silisia o Pampilien, se ap lel ong Mira en Lisia,',
        6: 'I wasa kaun en saunpei o diarada sop en Aleksandrien pot, me pan maselang Italien, i ari kasau ong kit poa.',
        7: 'A kit pwapwand kokola, pong toto meid apwal ong kit lel ong Knidus, pwe ang me kawela; kit ari tangatang panangen Kreta, tang wong Salmone.',
        8: 'A meid apwal at dauli wasa o; kit ari lel ong sap eu, me ad a Kapitau mau koren iong kanim Lasäa.',
        9: 'A ansau lao daulier o a apwalar ong sailok sili, aki ran en kaisesol daulier, Paulus ap kotin panaui o',
        10: 'Masani ong irail: Ol oko, i asaer me sailok wet pan suedela a pan apwal kaualap, kaidin ong audepan sop o sop eta, pwe pil ong maur atail.',
        11: 'A kaun en saunpei o liki saunilil o saumas en sop o sang masan en Paulus.',
        12: 'A kapitau me sota non mau ong sop en mimieta ni ansaun kapau. Koren iong karos ari men samala sang wasa o, o re song, ma re sota kak ong lel Pöniks, pwen mimita wasa o ni ansaun kapau, i kapitau en Kreta eu, me mi ni pali air o pali apang.',
        13: 'A ang lao udo sang pali air, re ap kiki ong, me re pan pwaida, ap apiada paipung ko tangala liman Kreta.',
        14: 'A madang melimel udo sang Kreta, me ad a alepip en kisiniang.',
        15: 'A ang lao kapeila sop o, o sop solar kak ong, kit ap nenenla o peila.',
        16: 'Ni at tangala panangen dake tikitik eu, me ad a Klauda, me tar kis, a se solar kak ong koledi pot o.',
        17: 'Irail apiada i, pwen kak piradi ong ni sop o, ap lilidi, pwe re masak re de serada nan Sirte, ap pungipungidok sili.',
        18: 'Kit lao pungipungidok sili kaualap, manda ap kamararadar sop o.',
        19: 'A ni ran kasilu irail kase kila pein pa arail kapwa en sop o.',
        20: 'Kadekadeo ran totola sota katipin o sota usu, o melimel kalaimun u dong kit, ap solar at kaporopor en pitila.',
        21: 'A kit lao kaisesol warailar, Paulus ap pwarada nan pung arail masani: Ol oko mak eta, komail en peiki ong ia er o so masel sang Kreta, pwe kitail ender lel dong kaupatail.',
        22: 'A met i panaui komail, en kaporopor mau, pwe sota me pan mela, sop eta me pan ola.',
        23: 'Pwe tounlang en Kot, me sapwilim a ngai, o me i kin papa, me kotida imp ai pong,',
        24: 'Kotin masani: Paulus, koe der masak, koe pan wisike wong ren Sisa. A kilang, Kot me kotiki ong uk er karos me iang uk.',
        25: 'Ari ol oko komail kaporopor mau, pwe i kin poson Kot, me a masan pan pwaida.',
        26: 'A kitail pan serada nin dake eu.',
        27: 'A lao pong ngaul pa pong lar, kit peipei sili nan sed Adria. Ni ailep en pong toun sop o kasauiada, me se koren iong sap eu.',
        28: 'A irail lao kasedi men song, re ap diaradar, me ngap rieisok, o re kaila ekis wasa o kasedi men song, re ap diaradar, me ngap eisoklimau.',
        29: 'A re masak, se de serada pon mat, rap kasedi paipong paieu sang ni murin sop, ap mauki en ran pasang,',
        30: 'A toun sop o lao men pitila sang nin sop o, o re apiedi pot apot nan sed, dene re pan kasedi paipong kai ni mon sop o,',
        31: 'Paulus ap masani ong kaun o saunpei kan: Ma mepukat sota pan mimieta pon sop o, komail sota pan kak dorela.',
        32: 'Saunpei kan ap leke sang pot o kasela o ari.',
        33: 'A lao pan ran pasang, Paulus ap panaui irail, ren manga, masani: Nan a pong ngaul pa pong lar, me komail kin auiaui o kaisesol o sota manga.',
        34: 'Ngai ari panauki komail, en manga, pwe i me komail pil pan piti kila. Pwe sota pit en mong pit pan pupedi sang amen komail.',
        35: 'A lao masanier met, ap ale prot, danke Kot mo’rail karos. I lao pilitiki pasang ap sak.',
        36: 'Irail karos ap kaporopor maular o pil manga.',
        37: 'A kit karos me mi nan sop o, me riepuki isiakan wonumen.',
        38: 'Irail lao medier, rap kamararadar sop o, kasedi ong nan madau korn.',
        39: 'A lao wasa ran pasang, re sasa sap o, A re diaradar kapitau eu, me mad mia; i wasa re lamedar en walang sop ia, ma re pan kak ong.',
        40: 'Irail lao leke sang paipong ko, rap kase ir ala nan madau, o lapwada padil akan, o apiadar serok en moa ni ang o, ap tangala ni oror.',
        41: 'Irail lao lel ong mad eu, sop o serada o solar mokid. Mon sop o tengela, a muri ola nan iluk kan.',
        42: 'Saunpei ko ap men kamela me salidi kan, pwe amen de pan pitila sang.',
        43: 'A kaun en saunpei o men dorela Paulus, ap sota mueid ong irail me re men wia o masani: Me asa pampap, en lusedi ong nan madau pap wong sap o.',
        44: 'A me tei kan pon tenap de kisan sop o. A ap pwaida, me irail karos dorelar o lel ong sap o.',
    },
    28: {
        1: 'KIT lao pitilar, se ap rongadar, me dake o adaneki Melite.',
        2: 'A men liki kan me kadek ong kit kaualap, pwe irail saunda kisiniai o kasamo kit karos, pweki katau moremor o pweki kapau.',
        3: 'Paulus lao wasai tui pena o kidi ong nani iai, serpent men ap lusadar sang nani iai pweki karakar o teng ong ni lim a.',
        4: 'A men liki ko lao udial man o a tengeteng ni lim a, re ap kasokasoi nan pung arail: Melel aramas men et me kamelar aramas, a piti sanger nan madau, ap rialar.',
        5: 'I ari sipede wong man o nani iai o sota mesued kot lel ong i.',
        6: 'Irail masamasan, ma a sota pan umposada de pupedi matala, a re lao masamasan warai o kilang, me a so suedi ong, re wukidalar ar lamelam o katitiki, me dene kot amen.',
        7: 'Saupeidi en dake o, me maraneki Puplius, kin sapaneki wasa o, kasamo o apapwali kit ran silu.',
        8: 'A sam en Puplius wononeki somau karakar o somau nta. I me Paulus koti dong re a kapakapaki, pwil lim a kan po a, kakeladar i.',
        9: 'Men en lao wiauier, karos me somau nin dake, ap kodo kakelailadar.',
        10: 'O re pil kaka kin kit kaualap. Kit lao maseldar, irail ari kidang pon sop o at kapinwar kasampwal.',
        11: 'A murin saunipong silu se iang sop en Aleksandrien pot, me mimi ni dake o ni ansaun kapau, me kilel en mpor.',
        12: 'A se keredi Serakus o kairu wasa o pong sili pong.',
        13: 'O sang wasa o se pidok tangatang lela dong Rekium, o manda ang air irepokedo o pong ta pong se lel ong Puteoli.',
        14: 'I wasa o se tu ong ia saulang kai, me poeki re at, sen mondi re’rail pong isi pong. Kit ari tangatang kokolang Rom.',
        15: 'O saulang kan en wasa o lao rongadar duen kit, re ap kodo tu ong kit Apipor o Tretapern; Paulus lao diar ir ada, ap kapinga Kot o kaporopor maular.',
        16: 'Kit lao lel Rom, kaun en saunpei ap pangalang kaun en silepa kan me salidi ko, a Paulus me saladok kotikot wasa toror, saunpei men me sinsila i.',
        17: 'Kadekadeo murin ran silu Paulus ap molipe pena saumas en Sus akai. Irail lao pokon penaer, a ap masani ong irail: Ri ai ko, nan sota mesued kot, me i wiadar ong aramas, de ong lamalam en sam atail akan, ari so, ngai me salidi o pakadara dong ni pa en men Rom akan sang Ierusalem.',
        18: 'Irail lao kalekalelapoki ia, ap men lapwa ia dar, pwe sota dip ai, me i en kame kila.',
        19: 'A Sus oko lao palian ia, i ap dorolang Sisa, kaidin ai men mpimpäki toun sap ai.',
        20: 'I me i ekera komail ki pena, i en kilang komail o kasokasoi ong komail, pweki en Sus akan ar kaporopor, me i salikidi sal mata pot et.',
        21: 'Irail sapeng i: Sota kisin likau, me se ale sang Iudäa duen komui, pil sota saulang amen, me kodido, me kaire kin kit o kadedeki, me dip omui mia.',
        22: 'A se men ronga sang komui duen omui lamelam, pwe se ronger duen pwin wet, me re kin palian wasa karos.',
        23: 'Irail ari kileledi ong i ran eu, ap pokon dong re a nan im en kairu. I ari kawewe ong irail o katitiki duen wein Kot, kapakaparok ki ong irail Iesus sang nan kapung en Moses o saukop akan, sang ni mansang lel nin sautik.',
        24: 'Akai irail me kamelele a padak a akai so.',
        25: 'Irail ari sota minimin pena nan pung arail, re ap pur pasang ni en Paulus a katitiki masan pot et: Melel, saukop Iesaia kopadar ren Ngen saraui ong sam atail akan.',
        26: 'Masani: Ko wong ren aramas pukat indada: Komail kin rong ap so lelapok ki o ngingar, ap sota dedeki.',
        27: 'Pwe mongiong en aramas pukat suedalar, o salong arail ponlar, o mas arail mair penaer, pwe re de ngar kida wasa mas ar, o rong kida wasa salong arail, o asaki nan mongiong arail o sapaledo, o I en kakele ir ada.',
        28: 'Komail ari en asa, me maur wot sang Kot mueidalang men liki kan o re pil pan peiki ong.',
        29: 'I lao masanier mepukat, Sus oko ap ko pasang o kapakaparok nan pung ar kaualap.',
        30: 'A Paulus kotikot nan im eu, me a kin isesa par riau, o kasamo karos, me ko dong i,',
        31: 'Kaweweda wein Kot o aima padapadaki duen Kaun Iesus Kristus pwe sota me inapwiedi.',
    },
}
